import { useState, useEffect } from 'react';
import { api } from '../lib/api.js';
import Markdown, { IconGlyph } from '../ui/md.jsx';
import { Link, useParams } from 'react-router-dom';
import { Lock, ShieldCheck, Cookie, Sparkles, Receipt, FileText, FileSignature, Printer, History, ArrowLeft, ArrowRight } from 'lucide-react';
import { PageHeader, Button, Card } from '../ui/ui.jsx';
import { Loading } from './pages.jsx';
import { DocSwitcher } from '../ui/doc-switcher.jsx';
import { useI18n } from '../i18n.jsx';

/* ─────────────────────────  Legal  ───────────────────────── */
export const LEGAL = {
  en: {
    privacy: { icon: Lock, title: 'Privacy Policy', body: [
      ['What we collect', 'An account requires your email and a display name. We store the content you submit (apps, plugins, themes, presets) and basic moderation records. Passwords are hashed with argon2id — never stored in plain text.'],
      ['A review you post on the home page', 'If you write a review of BetterCommunity from your dashboard, we store its text, the rating and the "about you" line you give, with your account. It is shown on the home page only after a moderator approves it, and then with your display name and a generated avatar, never your email. You can change or delete it at any time from your dashboard (a change goes back to the moderator before it is shown again), and closing your account deletes it.'],
      ['Analytics we run', 'With your cookie consent we collect privacy-friendly, first-party, anonymous analytics on THIS website: the page path and referrer; a daily-rotating anonymous visitor hash (no persistent identifier); a coarse device / browser / operating-system type; an approximate location (country, region and city) derived from your IP address, which we do not store long-term for this purpose; anonymous in-page interaction signals (which elements are clicked, edited or submitted — never the actual values you type into fields); and basic performance metrics (Web Vitals — including, for the responsiveness metric, the IDENTITY of the element the slowest interaction landed on, such as “button: Save”, never the value of a field). It is aggregated to understand how the site is used and to fix problems — no third-party trackers, no advertising, no cross-site profiling, and no attempt to identify you personally. You can decline at any time and declining loses no functionality.'],
      ['Session replay (off unless we turn it on)', 'Separately from the counts above, and only with the same analytics consent, this site can record a REPLAY of a visit — a reconstruction of what the page looked like and what was clicked, played back like a video. It is off by default and is switched on deliberately by an administrator; when it is off nothing is recorded and nothing is stored.\n\nWhat it never contains, by construction rather than by policy: the values you type. Fields are masked as the recording is created, so a password, an address or a message never exists in the recording to begin with — there is nothing to remove afterwards. Sign-in, two-factor and settings pages are never recorded at all. A recording is tied to the same daily-rotating anonymous visitor hash as the rest of analytics, so it cannot be joined to your account or followed from one day to the next.\n\nRecordings are kept only in a small rolling window — the oldest are deleted as new ones arrive — and only staff with the analytics permission can open one. Declining the analytics category, or leaving the banner alone, means no recording is ever made of your visit.'],
      ['Signed-in devices', 'When you sign in we record one row per device so you can see where your account is in use and end a session you do not recognise (Profile → Signed-in devices). That row holds the IP address the sign-in came from, an approximate location derived from it (country, region, city), your browser / operating system / device type, and the times the session started and was last active. This is kept for security — it is what lets you notice and stop an account takeover. You are the only ordinary reader of it: it is not shown to moderators, and it is not used for analytics or profiling. One exception, stated rather than buried: a SUPERADMIN — the highest staff tier, not a moderator — can view this list on an account and sign a device out, for account-recovery and abuse cases. Signing you out does not read your data or lock your account; you can sign straight back in. Signing a device out revokes it immediately; revoked rows are deleted after 30 days, and a session left idle past its token lifetime is deleted sooner. Unlike the analytics location described above, this one IS stored with your account for as long as the session lives.'],
      ['Sign-in attempts and new-sign-in alerts', 'Every attempt to sign in with a password is recorded: the address typed, the IP address it came from, and whether it succeeded or why not. This is what slows down password guessing and what staff look at after an attack. These rows are readable by administrators and by staff holding the history permission, and are kept 180 days by default; an administrator can change that window.\n\nWhen your account is used on a device or from a country it has never been used from, or after several failed attempts, we tell you: a notification and an e-mail with the time, the approximate place, the browser and the IP address, unless you mute sign-in alerts in your notification settings. To decide, we compare the new sign-in with the browser, operating system, device type and country of your earlier sessions, and we keep a record of each alert sent (its reason, that device description, the country and the IP address) for 180 days, so the same alert is not sent twice in a day.'],
      ['Content & files you host (Server-Repos)', 'When you host a Server-Repo or upload catalog files, we store those files as a neutral hosting provider so we can serve them for you. We do not inspect their contents beyond the moderation review and the automated integrity checks (SHA / per-file checksums) needed to run the platform, and we do not mine, sell, or repurpose them. One automated check does look at PICTURES: every uploaded image (including images inside an uploaded archive, and a linked avatar) gets a perceptual fingerprint — a 64-bit summary of what it looks like, from which the picture cannot be rebuilt — that is compared with the fingerprints of pictures other accounts uploaded, so that a copied logo or artwork reaches our moderators as a flag they check by eye. The fingerprint is kept as long as the picture is. If YOU place personal data inside your repo/files, you are the data controller for that data: you must have a lawful basis to store and distribute it, and you must not upload other people’s personal data without their consent or another legal basis. We process it only on your instructions, as your processor, to host and deliver it.'],
      ['Hosting & payments', 'If you purchase Server-Repo hosting, payment is processed by Stripe; we never see your card details. We store your subscription status, the timestamp at which you accepted these policies at checkout, and repo metadata.'],
      ['Answering a poll', 'A poll open to signed-in members records which options your account chose — that is one vote per account, and it is exact. A poll open to everybody has to keep out repeat votes without an account to count, so it stores a one-way fingerprint of your IP address and browser, salted per poll. It is not the daily-rotating analytics hash: it lasts as long as the poll, because a value that reset each night would let the same person vote again every day. It cannot be read back into an IP address, it is never used to identify or profile you, it is never joined to the analytics above, and it is not correlatable across polls. It is not cookie-consent gated, because it is not analytics: it is the mechanism that makes the count mean anything, and without it the poll could not be offered to people without accounts at all. It is deleted with the poll, and results are always reported with the anonymous half shown separately and labelled as an estimate.'],
      ['Messaging the people behind a repo, a catalogue or a profile', 'When you press Contact on a repo, a catalogue, a profile or a team, we store the conversation (subject, messages, the time of each) and who took part. Signed in, that is your account. Signed out, you give an e-mail address (and a name if you wish) so the other side can answer you: we store it, e-mail you a private link to the conversation, and record the IP address the message was sent from, which only staff can see and which exists to enforce the sending limits and to act on abuse. The person or team you wrote to sees your name or e-mail and your messages; nobody else does, except staff when a conversation is reported to them. Conversations are kept as long as the account or the e-mail address that owns them, and go with them when they are deleted. A team’s contact e-mail and phone, and the contact e-mail a repo served from its owner\u2019s own server must give, are published on purpose \u2014 that is what they are for.'],
      ['Using the public API', 'If you create an API key, we record how much each key is used — a per-day count of calls and errors, kept for as long as the key matters, so you and we can see what a key is doing. We also keep a SHORT-LIVED SAMPLE of individual calls: the method, the path, the status, how long it took, and the IP address the call came from. Retention is set by an administrator and is days, not months, and the sample exists to explain an incident rather than to build a history. The path is stored WITHOUT its query string, deliberately: private share links carry their secret there, and this table is readable by staff who have no access to those repositories.'],
      ['Downloading from a repository or a catalogue', 'When you, or the BetterModsManager app, fetch a hosted repository or a community catalogue, or download a file from one, we record the access: the IP address it came from, what was fetched (a file or item name, never the full address you used), whether it was a listing or a download, and when. For a repository we also keep the access key you presented, if any; for a catalogue, only whether a valid private share link was used, never the link itself. If you are signed in, or your app is linked to your account, the record also carries your account id and, if you linked one, your Discord id.\n\nThe owner of that repository or catalogue, the members of the team that owns it, and staff who manage repositories or catalogues can see these records as live traffic. They are kept 30 days, and at most the latest 5000 per repository or catalogue. Erasing an account does not remove them early: they expire on that schedule.'],
      ['Accounts you link: Steam, Twitch, YouTube, GitHub, Discord, Ko-fi', 'You can link other accounts to your profile. For Twitch, YouTube and GitHub we ask the provider who you are, once; for Steam, Steam confirms the sign-in and we read your public Steam profile; for Ko-fi you simply type your handle. We keep the account id, the name and the public profile address. The access a provider gives us for that check is used once and not stored. For Discord we keep your Discord id and username, from signing in with Discord or from linking through our bot.\n\nNone of them appears on your public profile unless you tick it there, Discord included. Unlinking one removes it, and closing your account removes them all.\n\nIf you try to link an account that already signs in to another BetterCommunity account, we refuse, and we tell you, and only you, which account holds it: its masked e-mail address and its display name. You have just proved you control the linked account, which is why this is yours to know. It reaches you through a cookie that expires after five minutes.'],
      ['Feedback, bug and crash reports', 'You can send us feedback, a bug report or a crash report, from this site or from one of our apps. We store what you send: the title and text, the app version and operating system, the technical details and log the app attaches, and any files you attach. We also store your account if you are signed in or your app is linked to it, the e-mail address you give if you give one, the creator id your app presents, and a hash of your IP address, used to group repeats and to enforce sending limits.\n\nAttachments are never public; staff who handle reports open them to investigate. By default attachments are deleted after 90 days, and a report marked resolved or ignored is deleted with its conversation 365 days after its last change; an administrator can change both. When staff delete a report, the report, its conversation and its attachments go together.'],
      ['E-mails we send you', 'We keep a log of every e-mail this site tries to send: the recipient address, which kind of e-mail it was, whether it was sent, failed, or was not sent because e-mail is switched off, how many attachments it had, and its subject and any error with links, addresses and codes removed. Never its content. The log exists to answer "I never got the mail". It is readable by staff who manage accounts, who see addresses masked in the list and whole only when they open one entry. It is kept 90 days, and at most the latest 20 000 entries. Entries sent to the address of an account are linked to it and removed if that account is erased on request; after an ordinary closure they expire on the 90-day rule.\n\nAn account created with a password has to confirm its e-mail address. Until it does, it can sign in and manage its own settings, but cannot publish, message other members or create API keys. We send one reminder after 7 days, and after 14 days an unconfirmed account that owns nothing is deleted.'],
      ['BMM telemetry', 'If you use the BetterModsManager app and leave its telemetry on, the app sends anonymous usage events, performance figures and — only when you enable it — session replays to a separate telemetry service we run. Each record carries only the install’s creator id, a public key; it never carries your account. A configurable share of installs is sampled (per kind of data and in total), decided on the device, so an install that is not in the sample sends nothing of that kind. From your account Settings you can ask for an export of everything held under a creator id linked to your account, or for its erasure; the confirmation and the export go to the address of your account and to nowhere else, and an install linked to an account cannot direct them elsewhere. The request, its state and its outcome are logged.'],
      ['BMM creator key and device fingerprint', 'BMM identifies an install by its creator id, a public key. From version 5 of that key, when BMM proves its creator id to us (when you send a bug or crash report, when you link the app to an account, and once per key while the app is linked to an account), the proof also carries a device fingerprint: four one-way hashes, computed on your computer, of (1) the motherboard, BIOS and processor identifiers, (2) the Windows installation identifiers, (3) the disk identifiers, and (4) how your graphics card draws a fixed test image, known as a canvas hash. No serial number, no picture and no raw value is ever sent, and every hash is salted with this site’s address, so it cannot be matched with what any other service receives.\n\nWhat we do with them: for each creator id we keep each hash, how many times it was seen and when. Moderators use this to tell whether a new creator id comes from the same computer as one that was banned or that already used a free offer. A person always decides; no rule acts on a match automatically. Canvas fingerprinting is a tracking technique and we call it that: it is used only for this anti-abuse purpose, never for analytics, advertising or profiling, and it is never shared.\n\nLegal basis: our legitimate interest in preventing the abuse of free offers and the evasion of bans (art. 6(1)(f) GDPR; art. 31 of the Swiss nLPD). Retention: each hash is deleted 180 days after it was last seen; the record of which key belongs to a creator id is kept while the id is in use. The hashes identify a device, so they are personal data: you can ask for access or erasure, or object, through the contact page, as for the rest of your data.'],
      ['Your rights (GDPR)', 'You can request access to, correction of, or deletion of your personal data at any time by contacting us. Deleting your account removes your personal data and unpublishes your content. A few records are kept, or expire on their own schedule instead; the Retention section lists them.'],
      ['Retention', 'How long each thing is kept, in the periods the service actually enforces rather than as a general promise:\n\n· YOUR ACCOUNT AND ITS CONTENT — while the account is open. Closing it schedules deletion 30 DAYS ahead, and reopening within those 30 days cancels it.\n· SIGN-IN SESSIONS — until they expire or you sign out. A revoked session’s record is removed 30 DAYS later.\n· REPOSITORY AND CATALOGUE ACCESS — 30 DAYS, and at most the latest 5000 events per repository or catalogue.\n· ANALYTICS — aggregated into daily counts. By default the underlying events are kept 365 DAYS for page views, 120 days for clicks and performance figures, 90 days for error reports and 30 days for session replays. An administrator can change these windows.\n· SIGN-IN ATTEMPTS — 180 DAYS by default. SIGN-IN ALERTS — 180 DAYS.\n· SENT-MAIL LOG — 90 DAYS, and at most the latest 20 000 entries.\n· BMM DEVICE FINGERPRINT HASHES — 180 DAYS after each was last seen.\n· FEEDBACK AND CRASH REPORTS — attachments 90 DAYS; a resolved or ignored report 365 DAYS after its last change. Both are defaults an administrator can change.\n· UNCONFIRMED SIGN-UPS — deleted after 14 DAYS, unless the account already owns something.\n· REPORTS, NOTICES AND MODERATION DECISIONS — kept with their outcome. They are how a repeat infringer is identified and how we can show what we did and why.\n· PAYMENT AND INVOICING RECORDS — 10 YEARS, which is the retention Swiss accounting law requires of business records.\n· BACKUPS — 14 DAYS. This is the period that matters after a deletion, so it is stated as its own line rather than left to be inferred.\n\nDeleting your account reaches our backups in two different ways, and saying otherwise would be the comfortable half of the truth. The per-row history the site keeps for undoing an administrative edit is encrypted with a key belonging to YOUR account alone; erasing the account destroys that key, so those snapshots become unreadable to everyone — including in any copy already held elsewhere — while other people’s remain intact. The full database backups taken for disaster recovery are a frozen copy of everything as it was on the day they were taken: an account erased today is still inside a backup taken yesterday, and it stays there until that backup is 14 days old and is deleted. Should we ever have to restore one, the erasures made since it was taken are re-applied before the site serves anyone again — restoring an old copy is not a way to undo a deletion.\n\nWhere a legal obligation requires us to keep something longer than the period above, that obligation wins, and it is the only thing that does.'],
      ['Closing your account, and coming back', 'Closing is scheduled 30 days ahead and reversible for that whole month. What happens at the end is ANONYMISATION rather than a row delete: your email, display name, profile and credentials are erased, while the records that must outlive an account — invoices, and the moderation history attached to what you published — are kept, because they are records about transactions and decisions rather than about your profile. One thing we keep is derived from your email: a one-way hash of the address, and nothing else. It exists so that if you sign up again with the same address we can recognise you and reattach your history — including any moderation record. We are stating that plainly rather than burying it, because it cuts both ways: it means a returning member keeps what they earned, and it means closing an account is not a way to leave a ban behind. Signing up with a different address starts genuinely fresh. The hash cannot be read back into your address, and it is used for nothing else.'],
      ['Security', 'We protect your data with specific measures, not just a promise of "reasonable" ones. Passwords are hashed with argon2id and are never stored or logged in the clear; two-factor authentication is available on every account and is required for staff and admin access. Traffic is served over HTTPS and the database is not exposed to the internet. We do NOT store your card details — payments go through Stripe, which holds them. Privileged staff actions are written to a tamper-evident, hash-chained audit log that can be verified for gaps. Abusive traffic is slowed and blocked automatically (rate limits, an automatic shield, and address/user-agent/creator bans), and a Content-Security-Policy constrains what can run in your browser. Repositories can be protected with a password or a signed key, and content you host is served over the same encrypted edge. We take a daily backup and can restore the service from it. No system is perfectly secure; if a breach materially affects you we notify you and, where the law requires, the supervisory authority within 72 hours (see "If there is a data breach").'],
      ['Age', 'BetterCommunity is not directed at children. In the EU and EEA you must be at least 16, which is the age Article 8 of the GDPR sets — unless the country you live in has lowered it, which some have, to no less than 13. Everywhere else the minimum is 13. If you are unsure which applies to you, it is 16.'],
      ['Donations through Ko-fi', 'Donations are made on Ko-fi, not here, so your payment is handled entirely under Ko-fi’s own terms and privacy policy and we never see your card.' + '\n\nWhat does reach us is a notification from Ko-fi for each donation, and we keep it: the DISPLAY NAME you donated under, the EMAIL Ko-fi passes on where you provided one, the amount and currency, whether it was a one-off or a monthly subscription, and the date. We keep it to recognise supporters, to answer questions about a payment, and because it is an accounting record. If the e-mail Ko-fi passes on is the address of an account here, that account gets a one-time hosting discount code and any Ko-fi supporter badge. The goal bar on the site shows only a total and the number of tips, never a name.' + '\n\nThis is the one case where we may hold data about somebody who never created an account. Article 14 of the GDPR is why it is written here rather than assumed. You can ask us to erase it through the Contact page — subject only to the retention periods accounting law imposes on records of money received.'],
      ['Data processors', 'These are everyone who receives data because of something this service does. Each is used for one purpose and nothing else.\n\n· STRIPE — payments, and payouts to marketplace sellers. Card details go to Stripe and never to us. If you SELL on a marketplace, you also open a Stripe account of your own through us: the identity and bank details Stripe requires to pay you go to Stripe directly, and we see only whether that account is enabled and what Stripe still needs from it.\n· KO-FI — donations. Ko-fi tells us about each one; what it sends is described above.\n· GOOGLE — sign-in, if you choose "Continue with Google", and linking a YouTube channel, if you choose to. Separately, and only with your analytics consent, a Google tag.\n· GITHUB — sign-in, if you choose "Continue with GitHub".\n· DISCORD — sign-in, account linking, and our community bot.\n· STEAM and TWITCH — linking those accounts to your profile, if you choose to.\n· YOUTUBE — embedded video only, loaded from youtube-nocookie.com, and only on a page that actually contains one.\n· OUR HOSTING AND OBJECT-STORAGE PROVIDER — the servers and the files themselves.\n· OUR E-MAIL SENDING SERVICE — delivers the e-mails this site sends.\n\nTwo things that are NOT processors: your approximate location is looked up in a database on our own server, so your IP address is not sent to a geolocation service; and our server checks Stripe’s public status page to know whether payments work, a request that carries nothing about you.\n\nSigning in with Google, GitHub or Discord is optional and never required: an email and a password work everywhere they do. Choosing one tells that provider you signed in here. Each only receives the data needed for its function and is bound by a data-processing agreement.{{dpa}}'],
      ['Make Your Own requests', 'If you use the paid "Make Your Own" service, we store the details you submit (product name, objective, description and any logo URL you provide), the conversation with our team, any files exchanged, and the payment records. That includes the quotes we send you and the files we deliver. We use them only to provide the service. The conversation is readable by the staff member the request is assigned to and by administrators — not by other members, and never publicly. Do not put other people’s personal data into a request without a lawful basis. Two things worth knowing before you start one: a commission record is a FINANCIAL record, so unlike most of your data it is kept when you close your account (the same rule as invoices — the profile is anonymised, the transaction record is not); and any file you attach or we deliver stays in the conversation for as long as the record does, so send a link rather than an attachment if you would rather it did not. A delivered file is kept for 30 days after delivery, or 7 days after your first download, whichever comes first; your first download is recorded (who, when) in the conversation as proof of delivery. Archiving a request deletes its attachments and delivered files and keeps the messages.'],
      ['Legal bases (GDPR Art. 6)', 'We process your data on these bases: performance of our contract with you (account, hosting, payments); your consent (optional analytics, Discord linking); our legitimate interests (security, abuse prevention, service improvement) balanced against your rights; and compliance with legal obligations. You can withdraw consent at any time without affecting prior processing.'],
      ['International transfers', 'Some processors (e.g. Stripe, or an analytics / Google tag if you enable it) may process data outside your country, including outside the EEA/UK. Where they do, transfers rely on appropriate safeguards such as the EU Standard Contractual Clauses or an adequacy decision.'],
      ['Your rights & how to exercise them', 'Under the GDPR/UK-GDPR you may access, rectify, erase, restrict or object to processing, withdraw consent, and request portability of your data. Reach us via the Contact page; we respond within one month. You also have the right to lodge a complaint with your local data-protection supervisory authority.'],
      ['No automated decisions', 'We do not carry out automated decision-making or profiling that produces legal or similarly significant effects on you.'],
      ['If there is a data breach', 'If personal data is breached in a way that is likely to result in a risk to your rights and freedoms, we notify the competent supervisory authority within 72 HOURS of becoming aware of it, as Article 33 of the GDPR requires — and where a delay is unavoidable, we say why.\n\nIf the risk to you is HIGH, we also tell you directly and without undue delay: what happened, what data it involved, what we think it means for you, and what we are doing about it. We will not defer notification pending certainty as to the cause.\n\nThe Swiss Federal Act on Data Protection imposes a parallel duty to report to the Federal Data Protection and Information Commissioner, which we meet in the same way.'],
      ['Swiss data protection (FADP), alongside the GDPR', 'We are established in Switzerland, so the revised Federal Act on Data Protection (FADP / nFADP, SR 235.1) applies to us directly. The GDPR applies in addition, because we offer this service to people in the EU and EEA.\n\nThe two regimes confer substantially the same rights — access, rectification, erasure, objection and portability — and we operate a single procedure for both. Exercise them the same way, through the Contact page. Switzerland benefits from a European Commission adequacy decision, so data reaching us from the EU does not need a separate transfer mechanism.\n\nWhich authority you complain to depends on where you are: in Switzerland, the Federal Data Protection and Information Commissioner (FDPIC); in the EU or EEA, your local supervisory authority. Either can be approached without going through us first.'],
      ['Data controller & contact', 'The data controller is the operator of BetterCommunity. For any privacy request or question — access, deletion, portability, or to withdraw consent — reach us through the Contact page.'],
    ] },
    terms: { icon: ShieldCheck, title: 'Terms of Service', body: [
      ['Accounts', 'You are responsible for activity under your account and for the content you submit. Keep your credentials safe.'],
      ['Content & moderation', 'Submissions are reviewed before publication. We may reject or remove content that is illegal, malicious, infringing, or violates these terms. You retain ownership of what you upload and grant us a licence to host and distribute it within the platform.'],
      ['Review & validation times', 'Every submission and update is queued for manual review and stays hidden (PENDING) until an admin approves it. We aim to review within 72 hours, but provide no guaranteed turnaround and may take longer during high volume. Plugin/theme files and hosted-repo content are automatically re-checked (SHA / per-file checksums) on every change and must pass before they can go live. We may re-review, re-validate, or unpublish previously approved content at any time.'],
      ['Copyright & hosted content rules', 'You may only upload or host content you own or are licensed to distribute. The following are strictly prohibited: copyrighted material without permission, paid or leaked third-party assets, malware or obfuscated payloads, illegal content, and anything infringing a trademark or another creator’s rights. Hosted Server-Repos must respect the original creators’ licences.'],
      ['What we are, and what we are not, responsible for', 'BetterCommunity is a hosting and distribution service. The content on it — mods, catalogs, repositories, themes, plugins, comments, files — is uploaded by its users, and the person who uploaded it is responsible for it. We do not pre-screen uploads and we have no general obligation to monitor them; we act on what is reported to us and on what we find. Curated or “official” listings are the exception in one direction only: reviewing an item means we looked at it, not that we warrant it, and it does not make us its author. Nothing here limits liability that cannot lawfully be limited — including for our own fraud, or for death or personal injury caused by our negligence.'],
      ['Listings that point somewhere else', 'A large part of what is listed here is a LINK, not a file. A repository entry, a catalog item or a source can point at GitHub, at a creator’s own server, at a Server-Repo we do not run. For those we store the listing — a name, a description, an icon, a URL — and nothing more. The file itself never touches our machines.\n\nThis is a limitation on what a report addressed to us can achieve. When a listing points elsewhere, everything we can do is on our side of the link:\n\n· remove the listing, so this service stops sending anybody there;\n· block the URL or the domain from being listed again;\n· act against the account that posted it, up to termination.\n\nWhat we CANNOT do is delete the file, edit it, or make it unavailable to somebody who already has the address. The file is neither ours nor held by us. A rights holder who notifies only us will find the material still available, because delisting removes the reference and not its object. Notice should also be given to the party actually hosting the file; where that party is identifiable we will say who it appears to be, without warranting the accuracy of that identification.\n\nWe delist on a valid report without first determining whether linking engages our liability. Storing content and referring to it are distinct acts under the DSA, the LCEN and Swiss law, but that question is for a court, and we do not treat it as a reason to defer action. Content we host ourselves is governed by the sections above; this section concerns the remainder.'],
      ['Which law applies to a report', 'This service is operated from Switzerland under Swiss law, hosted in France, and used from everywhere. That means more than one regime can apply to the same report, so the routes are set out separately rather than merged into one that fits nobody:\n\n· ANY illegal or infringing content — the reporting system below. One route, one queue, read by a person. Use it if you are unsure, which is most of the time.\n· ILLEGAL CONTENT, from within the EU — the same route, which is built to meet Article 16 of the Digital Services Act (Regulation (EU) 2022/2065) so that a notice through it gives us actual knowledge in EU law too.\n· CONTENT HOSTED IN FRANCE — the LCEN form below. It is not compulsory, but a notification in that form is what makes us legally presumed to know, which starts our obligation to act.\n· COPYRIGHT, wherever you are — the same notice-and-action mechanism. Copyright is a kind of illegality, not a separate queue, and one route that works is better than two that half-work.\n· COPYRIGHT, under Swiss law — the Swiss section below, which adds one duty the others do not have.\n\nWe do not operate a US DMCA notice-and-counter-notice procedure and make no claim to §512 safe harbour — we are not established there. A copyright claim from the United States is handled under the mechanism above, like any other.\n\nYou do not have to work out which one you fall under. Send what you have through the Contact page and say what is wrong and where; we will treat it under whichever regime gives it effect. The forms exist because using one gets you a stronger legal position, not because we will ignore you otherwise.'],
      ['How the reporting system works', 'The procedure has four stages.\n\n1. REPORT. Anyone can tell us about content they believe is illegal or infringes a right, through the notice form at /report — which asks for every element a notice needs and lets you point at the exact file — or the report control next to the content itself. No account is needed to report.\n2. RIGHTS HOLDERS. If you hold a right, say which work, where it is on this service, and on what basis you hold it. That is sufficient for us to act. The formal requirements of particular legal regimes are set out in the sections below.\n3. REVIEW AND ACT. A person reads it — no automated decision-making. If it is clear, we remove or disable the content and tell whoever posted it, with reasons and how to challenge it. Where the position is not clear, we say so. We are not a court and cannot determine competing claims of ownership.\n4. KEEP IT DOWN. Content we have removed after a report is prevented from being put back through this service, within what we can technically and reasonably do. See the next section for exactly when Swiss law makes that a duty rather than a policy.\n\nEvery report is recorded together with its outcome.'],
      ['Notice and action (EU — DSA Article 16)', 'Anyone, anywhere, can tell us about content they consider illegal. Send it through the Contact page. Under Article 16(2) a notice needs four things, and a notice that has them gives us ACTUAL KNOWLEDGE of the content — which is the point of sending one:\n\n1. A substantiated explanation of WHY you consider the content illegal.\n2. The exact electronic location: a URL, or the repository / catalog / item name and the path of the file inside it.\n3. Your name and e-mail address. (Not required for reports concerning offences under Articles 3–7 of Directive 2011/93/EU.)\n4. A statement that you believe in good faith that what you have said is accurate and complete.\n\nWhat we do: we confirm receipt, decide without undue delay, and tell you the outcome. If we remove or restrict something, the person who posted it receives a statement of reasons — what was done, why, on what legal or contractual basis, and how to challenge it. We do not use automated decision-making for this; a person reads every report.'],
      ['Notifying us under French law (LCEN)', 'Our hosting is in France, so the Law for Confidence in the Digital Economy (LCEN, no. 2004-575 of 21 June 2004) is available to you. Article 6-I-2 means we are not liable for what users store here unless we actually knew it was unlawful and failed to act promptly; Article 6-I-7 means we have no general obligation to monitor.\n\nA notification under Article 6-I-5 carries a presumption that we know, and to do that it must state:\n\n1. The date of the notification.\n2. If you are an individual: your surname, first names, occupation, address, nationality, date and place of birth. If a legal entity: its form, name, registered office, and the body legally representing it.\n3. Our name and address as the recipient.\n4. A description of the disputed content and its precise location.\n5. The reasons why it should be withdrawn, including the legal provisions relied on and the supporting facts.\n6. A copy of the letter you sent the author or publisher asking them to stop, withdraw or amend it — or proof that you could not reach them.\n\nPoint 6 is frequently omitted. French law requires that the author or publisher be approached first, or that the attempt be evidenced.\n\nAnd the warning that matters most here — Article 6-I-4 makes it a CRIMINAL OFFENCE, punishable by one year’s imprisonment and a €15,000 fine, to present content as unlawful in order to obtain its removal while knowing that this information is inaccurate. '],
      ['Copyright under Swiss law (CopA / URG, SR 231.1)', 'Swiss law prescribes no general notice-and-takedown procedure and no required form of notice. Article 39d of the Copyright Act imposes a specific and narrowly drawn obligation, reproduced below in substance.\n\nA hosting provider must prevent a work from being unlawfully made available again through its service when ALL THREE of the following hold:\n\na. the work has already been unlawfully made available through the SAME service;\nb. the provider HAS BEEN NOTIFIED of that infringement; and\nc. the service has created a PARTICULAR RISK of such infringement, in particular through a technical mode of operation or an economic orientation that encourages infringement.\n\nParagraph 2 limits it to the technical and economic measures that can reasonably be expected, in proportion to that risk. Article 62 paragraph 1bis makes a breach of Article 39d something a rights holder can go to court over.\n\nCondition (c) governs whether the obligation attaches at all, and is directed at services whose design or commercial orientation encourages infringement. We do not consider this service to fall within it and make no claim that Article 39d applies to us. We nonetheless prevent removed content from being restored, as a matter of policy rather than statutory obligation.\n\nSeparately from copyright, Article 28a of the Swiss Civil Code permits a person to act against anyone PARTICIPATING in an infringement of their personality rights, and Swiss courts have held that a host may be such a participant. Complaints concerning privacy and impersonation are therefore acted on directly and need not be framed as copyright claims.\n\nWhere no statute prescribes otherwise we follow the notice-and-takedown practice of the SIMSA Code of Conduct Hosting, the Swiss industry standard.'],
      ['How to reach us, and how authorities reach us', 'A single electronic point of contact serves all purposes: the Contact page. It is not an automated system; submissions are read by a natural person. It is the address for reports, complaints about a decision, rights-holder notices and privacy requests.\n\nMember State authorities, the European Commission and the European Board for Digital Services use the same address, as do the authorities of Switzerland and France. No separate channel is required for official requests.\n\nWe work in ENGLISH and FRENCH. Notices in either language are handled without translation. Notices in other languages are also handled, but response times are longer and accuracy cannot be assured; use of one of the two working languages is recommended.'],
      ['How we moderate, stated in advance', 'The following sets out our content-moderation policy in full, as required by Article 14 of the DSA.\n\nWHAT WE ACT ON. Content that is unlawful, that infringes somebody’s rights, or that breaks the Acceptable use rules above. No other ground is applied. Neither disapproval of content nor the volume of complaints received about it constitutes a ground.\n\nWHO DECIDES. A natural person. Every submission and every update is queued and stays hidden until somebody reviews it, and every removal, restriction, demotion or suspension is a human decision. We run automated measures — anti-bot filters at the edge, spam and abuse heuristics, rate limits — but they guard access to the service; they do not decide whether your content stays up.\n\nWHAT WE CAN DO. Refuse or remove an item, hide it pending review, delist a link, restrict visibility, suspend an account, or terminate one. The measure applied is the least restrictive one adequate to the breach.\n\nWITH WHAT REGARD. Diligently, objectively and proportionately, with regard to the fundamental rights of everybody involved — including the freedom of expression of the person who posted. We do not act on unreasoned demands, and every decision is issued with reasons and with the means of challenging it.'],
      ['When we tell the police', 'If we become aware of information giving rise to a suspicion that a criminal offence involving a THREAT TO THE LIFE OR SAFETY of a person has taken place, is taking place or is likely to take place, we inform the law enforcement or judicial authorities of the Member State concerned, or Europol where no Member State is identifiable, and we pass on what we know. This is Article 18 of the DSA and it is not discretionary.\n\nThis is the only circumstance in which we approach the authorities on our own initiative. Ordinary breaches of these terms, copyright disputes, and content we have removed are not reported. Separately, we answer lawful orders from authorities — Swiss, French, or an EU Member State’s — and we tell the affected user that we did, unless the order or the law forbids it.'],
      ['Challenging what we decided (EU — DSA Articles 17, 20 and 21)', 'If we remove, restrict, demote or suspend something of yours, you get a statement of reasons: what we did, why, whether a report or our own checking triggered it, whether automation was involved, and how to challenge it.\n\nYou can challenge it with us, free, for at least six months after the decision — send it through the Contact page quoting the reference in the notice. A person reviews it, not the person who made the original call where that can be arranged, and we reverse decisions we got wrong.\n\nYou have AT LEAST SIX MONTHS from the decision to challenge it, and it costs nothing. If we cannot agree, EU users may take the dispute to a certified out-of-court dispute settlement body under Article 21. That does not remove your right to go to court, and neither does anything else on this page.\n\nAbuse cuts both ways. We suspend accounts that repeatedly post manifestly illegal content, and we also stop processing reports from anyone who repeatedly sends manifestly unfounded ones — after a warning, in both cases. A reporting channel that can be used as a weapon is a channel that stops working for the people who need it.'],
      ['Repeat infringers', 'We suspend and then terminate the accounts of repeat infringers, as Article 23 of the DSA requires of us. Each upheld notice counts as one strike against the account that uploaded the material; an appeal we uphold removes it. You are warned before a suspension, and told what the strikes are for.\n\nThis is not discretionary — a service that keeps hosting for somebody who keeps infringing loses the protection that lets it host anything at all. Termination for repeat infringement is not refunded.'],
      ['What we publish, and what we are exempt from', 'BetterCommunity is operated at the scale of a micro-enterprise. Under Article 19 of the DSA that exempts us from Articles 20 to 22 — the internal complaint-handling system, out-of-court dispute settlement, and the trusted-flagger priority — and Article 15(2) exempts us from publishing annual transparency reports.\n\nWe state the exemption rather than rely on it silently, because we provide most of what it exempts us from. The complaint procedure described in "Challenging what we decided" is offered as a binding undertaking and is free of charge. The right to refer a dispute to a certified out-of-court body is set out because EU users hold it against non-exempt providers. We do NOT undertake to give trusted flaggers priority handling.\n\nShould the service cease to qualify for the exemption, these obligations will apply and this section will be amended accordingly.'],
      ['Trademarks, and everything that is not copyright', 'Trademark complaints, impersonation and privacy complaints go through the same notice-and-action mechanism as everything else — there is one queue, and a person reads it. What differs is what we can do: we are not a court and cannot rule on who owns a name, so for a trademark or a personality-rights claim we act on what is clear and tell you when it is not. Send them through the Contact page describing what is wrong and where. Content that is illegal where we operate is removed on sight, without waiting for a notice.'],
      ['Hosting', 'Hosted Server-Repos are subject to the storage, upload and capacity limits we set. Updates require a valid SHA. Abuse, illegal content, or excessive resource use may lead to suspension.'],
      ['Speeds, and what the Mbps figure means', 'Every plan states an upload speed in Mbps. That number is a CEILING, not a floor and not a guarantee: it is the maximum rate we will let a transfer reach, and what you actually get at any moment is whatever the network, the disks, the other traffic on the machine and your own connection allow. It will frequently be lower, and we do not promise an average, a minimum, or a percentile.\n\nThe same is true of download speed, for which no plan states a figure at all — it is neither limited by us nor promised by us.\n\nWe do not offer a service-level agreement on throughput, and no part of a plan\'s price is attributable to a particular speed being sustained. A transfer slower than the ceiling is the service operating as described. What we do undertake is not to throttle you BELOW your plan\'s ceiling as a matter of policy — the cap is the only deliberate limit — and to tell you if we ever have to apply another one, why, and for how long.\n\nSustained use that degrades the service for other people is covered by the resource-use clause above, and is handled by talking to you first.'],
      ['Data & content you host', 'You are solely responsible for everything you upload, host, or distribute through the service, including its legality and any personal data it contains. You warrant that you have the right to store and share it and that it complies with all applicable laws (including data-protection and copyright law). We act only as a neutral hosting/storage provider and, where your content contains personal data, as your data processor acting on your instructions — you remain the data controller. We do not back up your hosted data for you; keep your own copy. You agree to indemnify and hold us harmless from any third-party claim, loss, or liability arising out of the content or data you host.'],
      ['Downloads & use of software and content — at your own risk', 'BetterCommunity lets you download and use the Better* applications (such as BMM, BSM and BetterInstaller) and community-submitted content (mods, plugins, themes, presets and hosted Server-Repos). All of it is provided “as is”, with no warranty of fitness, safety, compatibility or result. You download, install and use it entirely at your own risk. To the maximum extent permitted by law we accept no responsibility for any consequence of downloading or using anything obtained through the platform — including damage to your device, operating system or other software, loss or corruption of files, game or save-file corruption, incompatibility, or any suspension, ban, or penalty imposed on you by a third-party game, storefront, service, or publisher. Verify what you install and keep your own backups.'],
      ['Third-party content & no endorsement', 'Community content is created and published by its authors, not by us. Our moderation and automated integrity checks aim to catch obvious abuse and malware, but they are not a guarantee of safety, quality, legality, or suitability, and listing or hosting content is never an endorsement of it. You alone are responsible for complying with the terms, licences, and rules of any third-party game, platform, mod loader, or software you use this content with — some modifications may breach those third parties’ own terms, and any resulting consequence (including account bans on those services) is yours alone.'],
      ['Accepting these terms', 'You must accept these Terms and the Payments & Refunds policy before you can pay for any hosting or feature. We record the date and time of your acceptance. If we materially change these terms, a new acceptance may be required before your next purchase.'],
      ['Commissioned work (Make Your Own)', 'The optional "Make Your Own" service lets you pay a consultation fee to discuss a product you want built (for example a Discord bot, an app, a website, or a custom job such as a code security review) and receive advice plus a written quote. The consultation fee pays for that advice and the quote only — it is NOT the price of the product, and no build work begins until you approve and pay the separate quote. Timelines are estimates, not guarantees. You must hold the rights to any materials you provide (names, logos, assets, and — for a security review — the code or system to be examined, which you confirm you are authorised to have tested), and you are responsible for the legality and intended use of what you ask us to build; we may decline or stop any request that is illegal, infringing, or abusive. Delivered work is provided "as is"; each quote states whether it includes source code. Unless a quote says otherwise, once you have paid in full you receive the right to use the delivered product for the purpose described, while we keep ownership of our pre-existing tools, libraries and general know-how. Security-review findings are best-effort and are never a guarantee that a product is free of vulnerabilities. Refunds for this service are covered in the Payments & Refunds policy.'],
      ['Quotes (Make Your Own)', 'A quote is an itemised offer with a total, a currency, and a date it is valid until. It is an offer, not a contract: until you pay it, either side can walk away — you may reject it, and we may withdraw it (for example if what you asked for changes, if our costs change, or if we can no longer take the work). Past its validity date a quote is no longer binding on us and we may reissue it at a different price. Paying a quote is what commissions the work, and what you are commissioning is what that quote describes — anything outside it is a new quote, not an included revision. A quote states whether it includes source code; where it does not, you receive the working product and we keep the source. Requests marked URGENT carry a higher consultation fee, shown before you pay it. We may decline a request, or pause new ones when the queue is full — in which case no consultation fee is taken.'],
      ['Payments', 'Hosting, listing features and marketplace products are billed via Stripe. Prices are shown before you confirm and may change with notice; a change never affects a period already paid for. If you ask for a refund mid-term, the unused portion is returned prorated to the day and the time already consumed is deducted; when we are at fault (a billing error or an outage we caused) we refund the affected period in full. See the Payments & Refunds policy for the full detail. Selling on a marketplace additionally requires a Stripe account of your own, which we help you open; we keep a commission on each sale and Stripe transfers the remainder to that account.'],
      ['Selling on a marketplace', 'If you list a product on a project marketplace, these terms apply to you as a seller in addition to everything else here.\n\nYou declare that you have the right to sell what you list and that its page describes it accurately. You are responsible for the content itself — that the key works, that the file is what it says it is, and that supplying it to a buyer infringes no third-party rights. We may delist a product, refuse a listing, or hold a payout where we believe on reasonable grounds that this is not the case, and we will tell you why.\n\nWe take a commission on each sale. It is shown to you before you list and does not change for a sale already made. To be paid you open a Stripe account through us and complete their checks; that account is yours, Stripe terms govern it, and until Stripe enables it your sales are held by us and paid over afterwards.\n\nWe are the merchant of record. The buyer pays us and we handle refunds and disputes, which means we can decide to refund a buyer without your agreement — and when we do, or when we lose a chargeback, we recover the amount from your share. If your share does not cover it, you owe us the difference.'],
      ['Payment failure & data retention', 'If a hosting subscription payment fails, you have at least 72 hours to renew it (currently seven days). After that window, the data stored for that subscription (hosted Server-Repo files and related content) is deleted without further notice and without backup.'],
      // N-hosting (agent-hosting-N): what a prepaid term guarantees, and what it does not.
      ['Prepaid terms: what we commit to', 'A hosting term can be paid in advance for 1, 6 or 12 months; nothing longer is sold. For the term you have paid, we commit to providing the plan you bought (its storage, its speed ceiling and the features listed for it) until the last day of that term. That is the whole commitment: we do not promise that the service, a plan or a price will still exist after the term you have paid, and nothing in these terms promises availability over several years.\n\nIf we discontinue the service, or a plan you have prepaid, before your term ends, we tell you in advance, by e-mail and in your account; your content stays downloadable until the service stops, and we refund the unused part of your prepaid term, prorated to the day, to the original payment method, without you having to ask. Terms longer than 12 months bought before this change are honoured to their end on the same conditions.\n\nA discount for staying subscribed (loyalty pricing) applies only at renewal, as the Payments & Refunds policy describes; it is not a promise of any future price.'],
      ['Discord bot plans', 'The Discord bot is free to add to any server. Some of its features, and some of its limits (how many role panels, voice lobbies, blocked words and so on), can require a paid Discord bot plan, either on its own or included with a storage plan. A plan is a monthly subscription that applies to the servers you choose among those you own or manage, up to the number the plan covers. What a server without a plan gets is shown on the Hosting page and may change with notice. When a plan ends, the settings of your server are kept, and the features and limits the plan added stop applying until you subscribe again. We may stop serving a server that breaks these terms, whatever its plan.'],
      ['Acceptable use', 'You agree not to abuse the service: no scraping or automated bulk access beyond our documented APIs, no overloading it, no unauthorised security probing, no circumventing quotas, sandboxing or integrity checks, and no uploading of malware, obfuscated payloads or illegal content. We may rate-limit, throttle, suspend, or block abusive activity at any time.\n\nThere is deliberately no prohibition on reverse engineering. The source of this platform is OPEN, and reading it, building on it or running your own copy is governed by its licence rather than by this policy \u2014 a term forbidding you to understand software we publish would be both incoherent and unenforceable. What is prohibited above is attacking the RUNNING SERVICE and the people using it, which is a different thing entirely.'],
      ['Enforcement', 'We enforce these terms strictly and at our sole discretion. Any violation may result in the immediate removal of content, suspension or permanent termination of your account and hosted repos — without prior notice and without refund — and, where the law requires, reporting to the competent authorities. Attempting to bypass moderation, integrity checks, quotas, or the sandbox is itself a violation. These measures are cumulative and in addition to any other remedy available to us.'],
      ['Governing law & changes', 'These terms are governed by SWISS law, the law of our place of establishment, without regard to conflict-of-law rules.\n\nThat choice does not, and cannot, displace three things. If you are a consumer, the mandatory protections of the country you live in still apply to you — a choice-of-law clause cannot take them away. The Digital Services Act applies to us because we offer this service in the EU, whatever our establishment. And the servers are in France, which puts what is stored on them within reach of French law and French courts regardless of this clause. Where any of those conflict with what is written here, they win. We may update these terms; material changes are announced and continued use after they take effect constitutes acceptance. If any provision is held unenforceable, the remainder stays in full force.'],
      ['Disclaimer & liability', 'The service is provided “as is” and “as available”, without warranties of any kind. To the maximum extent permitted by law, we are not liable for indirect, incidental, or consequential damages, and our total liability is limited to the amount you paid us in the 12 months preceding the claim.'],
    ] },
    cookies: { icon: Cookie, title: 'Cookie Policy', body: [
      ['What cookies are', 'Cookies and similar technologies (such as local storage) are small pieces of data stored in your browser. We group them by purpose below. You control the optional categories from the cookie banner and can change your choice at any time.'],
      ['What stays in your browser and is never sent', 'Most of what this site remembers about you never leaves your device, which is worth separating from the cookie question because none of it is a tracking decision. Your theme, language, translucency and layout preferences, whether you dismissed the intro, your in-app notification history, your draft submissions and — if you use the built-in authenticator — your TOTP secrets all live in your browser’s local storage. They are not transmitted to us, they are not part of analytics, and clearing site data removes them. The authenticator is the strongest case: it is built so its secrets NEVER reach a server, and you can encrypt them at rest with a passphrase only you know. The trade-off is the honest one — data we never receive is data we cannot restore for you.'],
      ['1 · Strictly necessary', 'A session cookie keeps you signed in, for up to 7 days. A few others exist for one task and expire on their own: one for 15 minutes after you confirm your identity again for a sensitive action; ones of 5 to 10 minutes that tie a sign-in or an account link to the browser that started it; one for 12 hours when you open a repository’s owner dashboard; and one for 4 hours on the telemetry dashboard. They are required for those things to work and cannot be switched off. Under the GDPR/ePrivacy rules no consent is needed for this category because it is essential to a service you asked for.'],
      ['2 · Analytics / statistics (optional — off by default)', 'Only if you accept the Analytics category do we enable privacy-friendly, first-party analytics: page path and referrer, a daily-rotating anonymous visitor hash, coarse device / browser / OS, approximate location (country / region / city) from your IP, anonymous in-page interaction signals (which elements are clicked/edited/submitted — never the values you type), and performance metrics (Web Vitals). Your choice is remembered in local storage, not in a tracking cookie, and you can decline with no loss of functionality.'],
      ['Third-party tags (Google Tag Manager)', 'When configured, we load Google Tag Manager as a third-party measurement tag. Its scripts and cookies load ONLY after you opt in to the Analytics category above — never before. Declining, or simply ignoring the banner, keeps it disabled. Google acts as our processor; some data may be transferred outside the EEA under appropriate safeguards (see the Privacy Policy). You can withdraw consent at any time.'],
      ['Managing your consent', 'Your preference is stored per browser. To change it, use the cookie setting on the Settings page, or clear this site’s storage and reload so the banner reappears. Withdrawing consent stops our own analytics at once; a Google tag already loaded stops when the page is next reloaded.'],
      ['No advertising', 'We never use advertising, cross-site, or social-media tracking cookies, and we never sell your data.'],
    ] },
    about: { icon: Sparkles, title: 'About us', body: [
      ['What BetterCommunity is', 'BetterCommunity is the shared home for the Better* ecosystem — a hub where the community discovers, shares, and hosts content for tools like Better Mods Manager (BMM), Better Sound Maker (BSM), and BetterInstaller. One account, one place: browse the catalogs, publish your own mods, plugins, themes and presets, and spin up a hosted Server-Repo.'],
      ['Our mission', 'To give creators a clean, honest, no-nonsense platform: no ads, no dark patterns, no selling your data. Files are integrity-checked on every change, and the whole thing is built to stay fast and lightweight.'],
      ['How things get published', 'There are two routes here and they are not the same, so we say which one you are looking at rather than let them read as one. The OFFICIAL catalog is checked before it appears: a submission stays invisible until somebody on the team has opened it and approved it, and a refusal comes with reasons. COMMUNITY catalogs and hosted Server-Repos go live when their owner decides — no queue and no wait. Each one shows the account that put it there, anyone can report a problem, and we suspend what breaks the rules. Checked after publication, then, and labelled as such everywhere it appears.'],
      ['The projects', 'BMM manages mods for supported games with a full plugin/theme system. BSM is a sound-preset catalog. BetterInstaller is a fast, modern installer for the suite. Server-Repos let creators host their own repositories with us, billed only for what they use. Every catalog is filled by the community, and contributors are credited on each project page.'],
      ['Building on it', 'The platform is open to other software: a REST API, OpenID Connect so people can sign in to your project with their account from here, and webhooks to be told when their content changes. There is no SDK, and a key takes a minute. If the thing you want does not exist and you would rather not build it yourself, a commission starts with a paid consultation — advice and a quote — and the work only begins once that quote is approved.'],
      ['Open & transparent', 'Our moderation rules, pricing, and privacy practices are all documented in these legal pages — no surprises. Every policy keeps its published versions, so you can read exactly the text you agreed to rather than the current one. Whether the site is up is a public page with its own probes, not a claim. Found a problem or have an idea? The Contact page and our Discord are the fastest ways to reach us.'],
      ['Support the project', 'BetterCommunity is community-funded. Hosting costs are covered by the paid Server-Repo plans and by donations on Ko-fi. Every tip goes straight to keeping the servers running — thank you.'],
    ] },
    refunds: { icon: Receipt, title: 'Payments & Refunds', body: [
      ['How billing works', 'Three things are paid: (1) hosted Server-Repos and storage pools, billed by the capacity, bandwidth and features you choose; (2) our-hosted catalog file storage above the free floor, and optional "featured" boosts; (3) products sold on a project\'s marketplace — either once or as a subscription that renews until you cancel it; and (4) an extra team slot beyond the number of teams an account may own for free — a one-off payment that stays with the account; and (5) Discord bot plans, a monthly subscription that unlocks bot features and higher limits on the servers you choose, sold on their own or included with a storage plan. Everything is processed by Stripe — we never see or store your card details. On a marketplace sale we keep a commission, shown to the seller before they list; the rest goes to the seller.'],
      ['Prices & currency', 'Prices are shown before you confirm, in the currency your payment method supports. Recurring plans renew automatically until you cancel. We may change prices with advance notice; a change never affects a period you have already paid for.'],
      ['If a price goes up', 'We email every affected subscriber before a price increase takes effect, at the address on the account, and post the same notice inside your account — an email can be missed, and the month it is missed in is the notice period. The notice states the current price, the new one, and the exact date it changes. The new price applies from your NEXT renewal, never to a period already paid for, and never mid-term on a prepaid plan. You can cancel before that renewal and keep your service until the end of the period you have paid — cancelling is always enough to decline an increase. Some plans are priced from our published per-GB and per-Mbps rates rather than a fixed figure, so their price follows those rates; the same notice and the same next-renewal rule apply.'],
      ['Free tier', 'Every account gets a free storage floor for hosting and a free catalog-upload floor — you only pay for what exceeds it. The free tier is genuinely free: no card required, no trial that silently converts.'],
      ['Cancelling', 'You can cancel a hosting subscription at any time from your dashboard. Cancellation stops the next renewal; your repo stays online until the end of the period you already paid for, then is taken offline.'],
      // N-hosting (agent-hosting-N): prepaid terms, discontinuation, and loyalty pricing.
      ['Prepaid terms', 'Paying ahead buys exactly the term you chose (1, 6 or 12 months) and nothing beyond it. The longer terms cost less per month, and that is the only thing the length changes. We do not sell terms longer than 12 months, because we do not promise the service years ahead. If we stop the service, or the plan you prepaid, before your term ends, we refund the unused part of the term, prorated to the day, without you having to ask, and your content stays downloadable until the service stops. Your own right to a prorated refund of the unused part (see "Refund policy") applies to a prepaid term like to any other.'],
      ['Loyalty discount', 'When we offer it, a hosting subscription that keeps renewing without a break gets a discount on its renewals once it reaches the steps shown on the Hosting page (for example 5 % after 3 months), up to the maximum stated there. The count starts on the day of the first payment. It starts again from zero if the subscription is cancelled (by you, or ended after failed payment retries), or if a renewal is paid later than the grace period after the end of the paid term (72 hours by default for a term renewed by hand, a week after a failed card payment). A new pool is a new subscription and starts at zero. The discount applies from the next renewal after a step is reached, never to a term already paid, and it is not refunded or credited when a subscription ends. Reducing or ending the loyalty steps counts as a price increase for the renewals it affects, and follows "If a price goes up".'],
      ['If your account is suspended or banned', 'A sanction stops the service, so it ends the money too: any active subscription is cancelled when a suspension or a ban is applied, and you are not billed again. What differs between the two is access — a SUSPENSION leaves you able to sign in, so you can read the reason, appeal it and download your invoices, while a BAN does not. In both cases your repositories, catalogs and items are SUSPENDED rather than deleted: nothing is destroyed, and if the sanction is lifted every one of them returns to the state it was in beforehand — a repository that was offline comes back offline. Subscriptions are the exception: they are cancelled at the payment provider and are not resurrected, so you would take out a new one. The period you had already paid for is not refunded automatically when the sanction is for cause; if you believe it was a mistake, contact us and a person will look.'],
      ['Refund policy', 'If you ask for a refund during a subscription you have already paid for, we return the part you have not yet used: the time already elapsed on the current period is deducted, and the remaining, unused portion is refunded, prorated to the day. Cancelling instead simply stops the next renewal and keeps your service until the end of the paid period. When the fault is ours — a billing error, a charge you did not make, or an extended outage we caused — we refund the affected period IN FULL, with no deduction for time consumed. Ask through the Contact page with your account email and the approximate date and amount; approved refunds return to the original payment method via Stripe within a few business days. The one exception to proration is a subscription cancelled for cause — a suspension or ban for a breach of these terms — see "If your account is suspended or banned".'],
      ['Marketplace purchases', 'A marketplace product is sold either ONCE or as a subscription. A subscription follows the same rules as everything else on this page: cancel to stop the next renewal, or ask for a refund and receive the unused part prorated to the day.\n\nA one-off product is DIGITAL CONTENT delivered the moment your payment clears — a key, a file, a licence, revealed text, or a Discord role. There is nothing to prorate and nothing to hand back: once a key is on your screen you have it. So the rule is different, and it is this. If the product is faulty, is not what its page described, or was never delivered at all, we refund it in full — tell us and we will not argue about it. If you simply changed your mind after it was delivered, a refund is at our discretion, because we cannot undo the delivery. The consumer right below is not affected by any of that.\n\nWHO YOU BOUGHT FROM. Some products are ours and some belong to another project on this site. Either way your contract for the PAYMENT is with us: we take the payment, we issue the invoice, and we are who you contact. We keep a commission and the rest is transferred to the seller. When we refund you, we recover that transfer from the seller — that is between us and them and never something you have to chase.'],
      ['Discord bot plans', 'A Discord bot plan is a subscription billed every month until you cancel it from Billing, and it follows the same rules as every other subscription on this page: cancelling stops the next renewal, a refund returns the unused part prorated to the day, and a fault of ours is refunded in full. When it ends, nothing on your server is deleted: its settings are kept and what the plan added stops applying. A plan included with a storage plan starts, renews and ends with that storage plan and is not billed separately.'],
      ['Failed payments & data deletion', 'If a renewal payment fails, you have at least 72 hours (currently seven days) to update your payment method and renew. After that window the data stored for that subscription (hosted Server-Repo files and related content) is deleted without further notice and without backup — so keep your own copy.'],
      ['Consultations & commissions (Make Your Own)', 'The consultation fee buys advice and a quote — a service we perform as soon as we reply to you. Once we have provided that advice it is non-refundable; if we are unable to help at all and give no advice, we refund it. A separate quote payment commissions bespoke work made to your instructions: once that work has begun it is non-refundable for the part already performed. If we fail to deliver what the quote describes and cannot put it right, we refund the portion not delivered. Approving a quote is a request for us to start immediately, which reduces or ends any statutory withdrawal right for work already done, as permitted by consumer law. A quote that expires, that you reject, or that we withdraw is not a charge and so is not a refund — nothing was taken. The consultation fee is separate from every quote and is not credited against one unless the quote itself says so. Delivered files are handed over through a dated download link: it works for THIRTY DAYS after delivery, or for SEVEN DAYS after your first download, whichever comes first, and your first download is recorded in the request’s conversation — that record is our proof of delivery and the start of the seven days. After the date the file is removed from our servers and cannot be re-issued, so download and keep your copy in time; once a request is archived the conversation is kept without its attachments.'],
      ['Your 14-day right to change your mind (EU/EEA consumers)', 'If you are a CONSUMER in the EU or EEA — buying for yourself and not for a business — you have FOURTEEN DAYS from the day you buy a hosting or listing subscription to withdraw from it, without giving any reason. Tell us through the Contact page within those fourteen days and we refund what you paid.\n\nOne exception applies, and is frequently overlooked. When you ask us to start immediately — which is what buying hosting normally means, since the service becomes available at once — you are asked to acknowledge that starting early reduces the right: you can still withdraw within the fourteen days, but we may keep an amount proportionate to what was already provided. If you ask us to start immediately AND the service is fully performed within the period, the right ends. We do not treat mere availability as full performance.\n\nA DIFFERENT RULE APPLIES TO DIGITAL CONTENT, and a marketplace product bought once is digital content. Where such content is supplied immediately, the right to withdraw ends once supply has begun — but only if you expressly asked for it to begin and acknowledged that you were losing the right. A marketplace checkout asks you for exactly that, and it is shown before you pay, not buried after. If you were not asked, the right is not lost and we will refund you. This does not touch a faulty or misdescribed product, which is refunded regardless.\n\nThis right is additional to, and independent of, the remainder of this policy. No term of this policy removes it, and any term purporting to do so would be unenforceable against a consumer.'],
      ['How to request a refund', 'Reach us through the Contact page with your account email and the approximate date/amount of the charge. We respond within a few business days. Approved refunds are returned to the original payment method via Stripe.'],
      ['Chargebacks', 'If something looks wrong, please contact us first — we can almost always resolve it faster than a bank dispute. Opening a chargeback without contacting us may result in suspension of the associated account and repos pending resolution.\n\nOn a marketplace sale the chargeback is ours to answer, because we took the payment. Where the product belonged to another seller and we lose the dispute, we recover the amount from their share.'],
    ] },
    submissions: { icon: FileText, title: 'Submission Terms', body: [
      ['What this covers', 'These terms apply when you ask us to list or host something: a Server-Repo, catalog files, or an "Other projects" listing. Submitting is a request for REVIEW — it creates no obligation on us to publish, host or keep anything, and a page or file only goes live once a person here has reviewed it.'],
      ['Open-source and closed-source', 'We list both. An OPEN-SOURCE project may be submitted by anyone — its owner, or someone who simply likes it — and must name its licence. A CLOSED-SOURCE project may be submitted ONLY by the rights-holder, and only with proof of rights attached: without proof we do not add it.'],
      ['Proof of rights, and how we handle it', 'Proof you upload for a closed-source listing (a licence, an invoice, a signed statement) is stored PRIVATELY — never served publicly, shown only to review staff and to you, and DELETED as soon as we reach a decision (approve, reject or withdraw). Upload the minimum needed to establish rights; do not upload other people’s personal data without a lawful basis.'],
      ['Your declarations', 'When you submit you declare that the information is accurate, that you have the right to request the listing, and — for a project that is yours — that you may grant the permission needed to display it. A false declaration is grounds to remove the listing and, for repeated abuse, to sanction the account.'],
      ['Paid reviews are non-refundable', 'A paid review fee buys a PLACE IN THE QUEUE and priority. It does not buy a listing, it does not change the answer, and it is NON-REFUNDABLE — including if the request is ultimately rejected. Any wait time shown is an ESTIMATE from how many requests are queued: not a promise, and paying does not guarantee a time. (Where consumer law grants a withdrawal right, that right still applies — see Payments & Refunds.)'],
      ['The contact thread', 'Each submission opens a private thread in your dashboard under "Reports & contact", where staff may ask for more detail and you can reply. It is readable only by you and staff.'],
      ['Removal and your rights (GDPR)', 'You can withdraw a pending request at any time, which deletes it and any proof. Approving or rejecting also deletes the proof. Your declaration (owner/fan, licence) is kept with the record so we can show why a listing exists. Exercise your GDPR rights (access, correction, deletion) through the Contact page; retention is in the Privacy Policy.'],
    ] },
    dpa: { icon: FileSignature, title: 'Data Processing Addendum', body: [
      ['What this is, and when it applies', 'Most of the time BetterCommunity decides why and how your data is used — for your account, your purchases, the pages you read — and the Privacy Policy is the document that describes that. This Addendum covers the OTHER situation: when YOU decide and we merely carry it out. That happens when you host a Server-Repo or a catalogue whose files or access logs concern other people, when you sell on a marketplace and we hold your buyers’ records for you, when you run a team, and when you add our Discord bot to a server you administer — it then keeps, on your behalf, activity counts, moderation records and, if you turn logging on, a log of what happens in that server. In those cases you are the CONTROLLER of that data under Article 4(7) of the GDPR, we are your PROCESSOR under Article 4(8), and this Addendum is the Article 28(3) contract between us. It is part of the Terms of Service, applies from the moment you use one of those features, and prevails over the Terms where the two disagree about personal data.'],
      ['Subject matter, duration, nature and purpose', 'SUBJECT MATTER: the personal data contained in, or generated by, the content and services you place with us — repository and catalogue files and their download logs, marketplace orders and buyer contact details, team membership, and Discord server activity, member records, moderation actions and logs collected by the bot at your request.\n\nDURATION: for as long as you use the feature concerned, plus the retention periods stated in the Privacy Policy’s "Retention" section, which are the periods the service actually enforces.\n\nNATURE: storage, serving to the people you authorise, counting, and — for the bot — collecting events from Discord, applying the moderation rules you configured, and writing the log entries you asked for. We do not read, profile or analyse this data for our own purposes.\n\nPURPOSE: providing the hosting, marketplace, team and community-bot features you chose, and nothing else.'],
      ['The data and the people concerned', 'CATEGORIES OF DATA: whatever your content contains (we do not inspect it), plus what the feature itself generates — IP addresses in repository and catalogue access logs, with the access key presented and, where the downloader is signed in or their app is linked, their account id and Discord id; names, email addresses and order details of marketplace buyers; Discord user ids, display names, avatars, message counts, voice time, reactions, join and leave dates, roles, warnings, timeouts, kicks and bans, and — only where you enable it — the message content and edits that a log category records.\n\nDATA SUBJECTS: the people who download from your repositories, your buyers, your team members, and the members of the Discord servers you administer.\n\nSPECIAL CATEGORIES: none of these features is designed for data revealing health, beliefs, sexual orientation, ethnicity or the like. If your content or your server contains such data, you must have a lawful basis for it under Article 9 and tell us before placing it with us; we may decline.'],
      ['Your obligations as controller', 'You warrant that you have a lawful basis for every processing you instruct, that the people concerned have been informed as Articles 13 and 14 require (a privacy notice for your buyers, a notice in your Discord server that the bot logs activity and what it logs), that you will not instruct anything unlawful, and that you will use the features’ own settings — log categories, retention, exemptions, who can see what — as the way you exercise your decisions. The bot’s logging and automod settings ARE your instructions: a category you turn on is data you have decided to collect, and a category you leave off is data we will not.'],
      ['Our obligations as processor', 'We process this data ONLY on your documented instructions, which are: the Terms, this Addendum, the settings you choose in the product, and any further written instruction you give through the Contact page. If we believe an instruction breaks the law we tell you before acting on it. Specifically, we:\n\n· grant access to your data only to staff bound by confidentiality who need it to run the service or to answer you;\n· apply the security measures described in the Privacy Policy’s "Security" section (argon2id password hashing, HTTPS everywhere, a database not exposed to the internet, two-factor authentication required for staff, a hash-chained audit log of privileged actions, rate limits and automatic blocking, daily backups) — these are the Article 32 measures and they are the ones the service actually runs, not a generic list;\n· help you answer requests from data subjects (access, rectification, erasure, restriction, portability, objection) that concern data we hold for you — most of them you can fulfil yourself with the product’s own tools (delete a file, delete a log entry, remove a member’s record, close the server’s dashboard), and where you cannot we act within a reasonable time on your written request;\n· help you with Articles 32 to 36 — security, breach notification, data-protection impact assessments and prior consultation — to the extent the information is ours to give;\n· delete or return the data at the end of the service as described below;\n· make available the information needed to show we comply, and allow audits as described below.'],
      ['Sub-processors', 'You authorise the sub-processors listed under "Data processors" in the Privacy Policy, each for the single purpose stated there. Our hosting and object-storage provider holds the servers and the files; Stripe holds the payment data of your buyers; Discord is the platform the bot operates on. We will tell you about any intended addition or replacement of a sub-processor at least THIRTY DAYS before it takes effect, by e-mail to the address of your account and by a note on the Privacy Policy page, and you may object within that period; if we cannot resolve the objection you may end the affected feature and we refund what you have prepaid for it. Every sub-processor is bound by a written contract imposing the same obligations as this Addendum, and we remain fully liable to you for their performance.'],
      ['Where the data is, and transfers outside the EEA', 'The service is operated for users in the European Union and the European Economic Area, and we prefer sub-processors that process there. Where a sub-processor processes personal data outside the EEA — Stripe, Google, GitHub and Discord are companies whose group includes entities in the United States — the transfer relies on an adequacy decision of the European Commission where one exists, and otherwise on the Standard Contractual Clauses adopted by the Commission, with the supplementary measures the sub-processor documents. We do not ourselves transfer your data outside the EEA except through those sub-processors and for those purposes.'],
      ['If there is a data breach', 'If we become aware of a personal-data breach affecting data we process for you, we notify you WITHOUT UNDUE DELAY and in any case within 48 hours of becoming aware — by e-mail to the address of your account — with what we know at that point: the nature of the breach, the categories and approximate number of records and people concerned, the likely consequences, and the measures taken or proposed. We keep adding to that notice as we learn more. The 72-hour clock in Article 33 for notifying the supervisory authority runs for you as controller; our notice is timed so you can meet it.'],
      ['Audits', 'On written request, at most once per twelve months unless a supervisory authority or a breach gives a reason, we provide the documentation that shows how we meet this Addendum — the Security section, our sub-processor list, the results of any security review we have had, and answers to a reasonable written questionnaire. If that is not enough, you or an independent auditor bound by confidentiality may audit the relevant parts of the service, at your cost, on thirty days’ notice, at a time that does not disrupt other customers, and without access to other customers’ data.'],
      ['End of the service: deletion or return', 'When you stop using a feature — you delete a repository or a catalogue, close a team, remove the bot from your server, or close your account — the data we hold for it is deleted within the retention periods the Privacy Policy states for that data (a removed server’s activity and logs are deleted at the next sweep, backups roll off within the backup retention period). Before that you can export what we hold: repository files and catalogues download as archives, marketplace orders export from your seller dashboard, and the bot’s member database and logs export from the server dashboard. We do not keep a copy once the retention period has run, except where a law requires us to.'],
      ['Liability and the rest', 'Each party is liable for the damage it causes by processing in breach of the GDPR, as Article 82 provides, and the limits of liability in the Terms of Service apply to this Addendum except where the GDPR does not allow them to. If any part of this Addendum is found invalid, the rest stands and the invalid part is read as closely to its intent as the law allows. This Addendum is governed by the law that governs the Terms, and the courts named there have jurisdiction. We may update this Addendum the way the Terms are updated; a change that reduces your protection is announced thirty days ahead and you may end the affected feature before it applies.'],
      ['Contact', 'Questions about this Addendum, instructions you want recorded, sub-processor objections and audit requests all go through the Contact page, which is the single electronic point of contact named in the Terms. For the identity of the controller when WE are the controller — your account, your purchases, this website — see the Privacy Policy.'],
    ] },
  },
  fr: {
    privacy: { icon: Lock, title: 'Politique de confidentialité', body: [
      ['Ce que nous collectons', 'Un compte requiert votre e-mail et un nom affiché. Nous stockons le contenu que vous soumettez (apps, plugins, thèmes, presets) et des données de modération. Les mots de passe sont hachés avec argon2id — jamais en clair.'],
      ['Un avis publié sur l’accueil', 'Si vous écrivez un avis sur BetterCommunity depuis votre tableau de bord, nous stockons son texte, la note et la ligne « à propos de vous » que vous donnez, avec votre compte. Il n’apparaît sur l’accueil qu’après l’approbation d’un modérateur, et alors avec votre nom affiché et un avatar généré, jamais votre e-mail. Vous pouvez le modifier ou le supprimer à tout moment depuis votre tableau de bord (une modification repasse par le modérateur avant d’être affichée de nouveau), et la fermeture de votre compte le supprime.'],
      ['Les statistiques que nous faisons', 'Avec votre accord cookies, nous collectons sur CE site des statistiques internes, anonymes et respectueuses de la vie privée : le chemin de page et le référent ; un hachage de visiteur anonyme qui change chaque jour (aucun identifiant persistant) ; un type d’appareil / navigateur / système approximatif ; une localisation approximative (pays, région et ville) dérivée de votre adresse IP, que nous ne conservons pas durablement à cette fin ; des signaux d’interaction anonymes dans la page (quels éléments sont cliqués, édités ou soumis — jamais les valeurs que vous saisissez) ; et des mesures de performance de base (Web Vitals — dont, pour la mesure de réactivité, l’IDENTITÉ de l’élément sur lequel l’interaction la plus lente a porté, par exemple « button: Save », jamais la valeur d’un champ). Elles sont agrégées pour comprendre l’usage du site et corriger les problèmes — aucun pisteur tiers, aucune publicité, aucun profilage inter-sites, et aucune tentative de vous identifier personnellement. Vous pouvez refuser à tout moment sans perte de fonctionnalité.'],
      ['Appareils connectés', 'Lorsque vous vous connectez, nous enregistrons une ligne par appareil afin que vous puissiez voir où votre compte est utilisé et mettre fin à une session que vous ne reconnais pas (Profil → Appareils connectés). Cette ligne contient l’adresse IP à l’origine de la connexion, une localisation approximative qui en découle (pays, région, ville), votre navigateur / système / type d’appareil, ainsi que les dates de début et de dernière activité de la session. C’est conservé pour des raisons de sécurité — c’est ce qui vous permet de repérer et d’arrêter un détournement de compte. Vous en êtes le seul lecteur ordinaire : ce n’est pas montré aux modérateurs, et ce n’est utilisé ni pour des statistiques ni pour du profilage. Une exception, énoncée plutôt qu’enfouie : un SUPERADMIN — le rang d’équipe le plus élevé, pas un modérateur — peut consulter cette liste sur un compte et déconnecter un appareil, pour les cas de récupération de compte et d’abus. Vous déconnecter ne lit pas vos données et ne verrouille pas votre compte ; vous pouvez vous reconnecter immédiatement. Déconnecter un appareil le révoque immédiatement ; les lignes révoquées sont supprimées au bout de 30 jours, et une session inactive au-delà de la durée de vie de son jeton l’est plus tôt. Contrairement à la localisation statistique décrite plus haut, celle-ci EST conservée avec votre compte tant que la session existe.'],
      ['Tentatives de connexion et alertes de nouvelle connexion', 'Chaque tentative de connexion par mot de passe est enregistrée : l’adresse saisie, l’adresse IP d’origine, et la réussite ou la raison de l’échec. C’est ce qui freine les essais de mots de passe et ce que l’équipe consulte après une attaque. Ces lignes sont lisibles par les administrateurs et par les membres de l’équipe qui ont la permission historique, et sont conservées 180 jours par défaut ; un administrateur peut changer ce délai.\n\nQuand votre compte est utilisé sur un appareil ou depuis un pays jamais vus, ou après plusieurs échecs, nous vous prévenons : une notification et un e-mail avec l’heure, le lieu approximatif, le navigateur et l’adresse IP, sauf si vous coupez les alertes de connexion dans vos réglages de notifications. Pour décider, nous comparons la nouvelle connexion au navigateur, au système, au type d’appareil et au pays de vos sessions précédentes, et nous gardons une trace de chaque alerte envoyée (sa raison, cette description d’appareil, le pays et l’adresse IP) pendant 180 jours, pour ne pas envoyer deux fois la même alerte dans la journée.'],
      ['Contenu & fichiers que vous hébergez (Server-Repos)', 'Quand vous hébergez un Server-Repo ou envoyez des fichiers de catalogue, nous stockons ces fichiers en tant qu’hébergeur neutre afin de les servir pour vous. Nous n’inspectons pas leur contenu au-delà de la revue de modération et des contrôles d’intégrité automatiques (SHA / checksums par fichier) nécessaires au fonctionnement de la plateforme, et nous ne les exploitons, vendons ni réutilisons jamais. Un contrôle automatique regarde toutefois les IMAGES : chaque image envoyée (y compris les images à l’intérieur d’une archive envoyée, et un avatar lié) reçoit une empreinte perceptuelle — un résumé de 64 bits de son apparence, à partir duquel l’image ne peut pas être reconstruite — comparée aux empreintes des images envoyées par d’autres comptes, pour qu’un logo ou une illustration copiés arrivent à nos modérateurs comme un signalement qu’ils vérifient à l’œil. L’empreinte est conservée aussi longtemps que l’image. Si vous placez des données personnelles dans votre dépôt/vos fichiers, vous en êtes le responsable de traitement : vous devez disposer d’une base légale pour les stocker et les distribuer, et vous ne devez pas envoyer les données personnelles d’autrui sans leur consentement ou une autre base légale. Nous ne les traitons que sur vos instructions, en tant que sous-traitant, pour les héberger et les diffuser.'],
      ['Hébergement & paiements', 'Si vous payez un hébergement de Server-Repo, le paiement est traité par Stripe ; nous ne voyons jamais votre carte. Nous stockons l’état de votre abonnement, l’horodatage de votre acceptation de ces politiques au paiement, et les métadonnées du dépôt.'],
      ['Répondre à un sondage', 'Un sondage réservé aux membres connectés enregistre les options choisies par votre compte — une voix par compte, et c’est exact. Un sondage ouvert à tous doit écarter les votes répétés sans compte à compter : il stocke donc une empreinte à sens unique de votre adresse IP et de votre navigateur, salée par sondage. Ce n’est pas le hachage statistique qui tourne chaque jour : elle dure autant que le sondage, parce qu’une valeur remise à zéro chaque nuit laisserait la même personne revoter tous les jours. Elle ne peut pas être retransformée en adresse IP, ne sert jamais à vous identifier ni à vous profiler, n’est jamais rapprochée des statistiques ci-dessus, et n’est pas corrélable d’un sondage à l’autre. Elle n’est pas soumise au consentement cookies, parce que ce ne sont pas des statistiques : c’est le mécanisme qui donne un sens au décompte, et sans lui le sondage ne pourrait pas être proposé aux personnes sans compte. Elle est supprimée avec le sondage, et les résultats affichent toujours la part anonyme à part, présentée comme une estimation.'],
      ['Écrire aux personnes derrière un dépôt, un catalogue ou un profil', 'Quand vous utilisez Contacter sur un dépôt, un catalogue, un profil ou une équipe, nous stockons la conversation (objet, messages, heure de chacun) et qui y participe. Connecté, c’est votre compte. Déconnecté, vous donnez une adresse e-mail (et un nom si vous le souhaitez) pour qu’on puisse vous répondre : nous la stockons, vous envoyons par e-mail un lien privé vers la conversation, et enregistrons l’adresse IP d’envoi, visible seulement par l’équipe, qui sert à appliquer les limites d’envoi et à agir en cas d’abus. La personne ou l’équipe à qui vous écrivez voit votre nom ou votre e-mail et vos messages ; personne d’autre, sauf l’équipe quand une conversation lui est signalée. Les conversations sont conservées aussi longtemps que le compte ou l’adresse e-mail à qui elles appartiennent, et partent avec eux quand ils sont supprimés. L’e-mail et le téléphone de contact d’une équipe, et l’e-mail de contact qu’un dépôt servi depuis le serveur de son propriétaire doit fournir, sont publiés volontairement : c’est leur raison d’être.'],
      ['Utiliser l’API publique', 'Si vous créez une clé API, nous enregistrons son usage — un compteur quotidien d’appels et d’erreurs, conservé tant que la clé compte, pour que vous et nous puissions voir ce qu’elle fait. Nous gardons aussi un ÉCHANTILLON DE COURTE DURÉE d’appels individuels : la méthode, le chemin, le statut, la durée et l’adresse IP d’origine. La durée de conservation est réglée par un administrateur et se compte en jours, pas en mois : cet échantillon sert à expliquer un incident, pas à constituer un historique. Le chemin est stocké SANS sa chaîne de requête, volontairement : les liens de partage privés y portent leur secret, et cette table est lisible par des membres de l’équipe qui n’ont aucun accès à ces dépôts.'],
      ['Télécharger depuis un dépôt ou un catalogue', 'Quand vous, ou l’application BetterModsManager, lisez un dépôt hébergé ou un catalogue communautaire, ou en téléchargez un fichier, nous enregistrons l’accès : l’adresse IP d’origine, ce qui a été lu (un nom de fichier ou d’élément, jamais l’adresse complète utilisée), s’il s’agit d’une lecture de liste ou d’un téléchargement, et l’heure. Pour un dépôt, nous gardons aussi la clé d’accès présentée, s’il y en a une ; pour un catalogue, seulement le fait qu’un lien de partage privé valide a été utilisé, jamais le lien lui-même. Si vous êtes connecté, ou si votre application est liée à votre compte, l’enregistrement porte aussi votre identifiant de compte et, si vous en avez lié un, votre identifiant Discord.\n\nLe propriétaire de ce dépôt ou de ce catalogue, les membres de l’équipe à qui il appartient, et l’équipe du site qui gère les dépôts ou les catalogues voient ces enregistrements comme trafic en direct. Ils sont conservés 30 jours, et au plus les 5000 derniers par dépôt ou catalogue. Effacer un compte ne les supprime pas plus tôt : ils expirent selon ce délai.'],
      ['Comptes que vous liez : Steam, Twitch, YouTube, GitHub, Discord, Ko-fi', 'Vous pouvez lier d’autres comptes à votre profil. Pour Twitch, YouTube et GitHub, nous demandons une fois au fournisseur qui vous êtes ; pour Steam, Steam confirme la connexion et nous lisons votre profil Steam public ; pour Ko-fi, vous saisissez simplement votre pseudo. Nous gardons l’identifiant du compte, le nom et l’adresse du profil public. L’accès que le fournisseur nous donne pour cette vérification sert une fois et n’est pas conservé. Pour Discord, nous gardons votre identifiant et votre pseudo Discord, issus de la connexion avec Discord ou de la liaison via notre bot.\n\nAucun n’apparaît sur votre profil public si vous ne le cochez pas, Discord compris. Délier un compte le supprime, et fermer votre compte les supprime tous.\n\nSi vous essayez de lier un compte qui sert déjà à se connecter à un autre compte BetterCommunity, nous refusons, et nous vous indiquons, à vous seul, quel compte le détient : son adresse e-mail masquée et son nom affiché. Vous venez de prouver que vous contrôlez le compte lié, c’est pourquoi cette information vous revient. Elle vous parvient par un cookie qui expire au bout de cinq minutes.'],
      ['Retours, rapports de bug et de plantage', 'Vous pouvez nous envoyer un retour, un rapport de bug ou de plantage, depuis ce site ou depuis une de nos applications. Nous stockons ce que vous envoyez : le titre et le texte, la version de l’application et le système, les détails techniques et le journal que l’application joint, et les fichiers que vous joignez. Nous stockons aussi votre compte si vous êtes connecté ou si votre application y est liée, l’adresse e-mail que vous donnez si vous en donnez une, l’identifiant créateur que présente votre application, et un hachage de votre adresse IP, qui sert à regrouper les doublons et à appliquer les limites d’envoi.\n\nLes pièces jointes ne sont jamais publiques ; l’équipe qui traite les rapports les ouvre pour enquêter. Par défaut, les pièces jointes sont supprimées après 90 jours, et un rapport marqué résolu ou ignoré est supprimé avec sa conversation 365 jours après sa dernière modification ; un administrateur peut changer ces deux délais. Quand l’équipe supprime un rapport, le rapport, sa conversation et ses pièces jointes partent ensemble.'],
      ['Les e-mails que nous vous envoyons', 'Nous tenons un journal de chaque e-mail que ce site essaie d’envoyer : l’adresse du destinataire, le type d’e-mail, s’il est parti, a échoué, ou n’est pas parti parce que l’e-mail est désactivé, le nombre de pièces jointes, et son objet et l’éventuelle erreur, liens, adresses et codes retirés. Jamais son contenu. Ce journal sert à répondre à « je n’ai jamais reçu le mail ». Il est lisible par les membres de l’équipe qui gèrent les comptes, qui voient les adresses masquées dans la liste et en entier seulement en ouvrant une entrée. Il est conservé 90 jours, et au plus les 20 000 dernières entrées. Les entrées envoyées à l’adresse d’un compte y sont rattachées et supprimées si ce compte est effacé sur demande ; après une fermeture ordinaire, elles expirent selon la règle des 90 jours.\n\nUn compte créé avec un mot de passe doit confirmer son adresse e-mail. En attendant, il peut se connecter et gérer ses propres réglages, mais ne peut ni publier, ni écrire aux autres membres, ni créer de clé API. Nous envoyons un rappel après 7 jours, et après 14 jours un compte non confirmé qui ne possède rien est supprimé.'],
      ['Télémétrie BMM', 'Si vous utilisez l’application BetterModsManager et laissez sa télémétrie active, l’application envoie des événements d’usage anonymes, des mesures de performance et — seulement si vous l’activez — des replays de session à un service de télémétrie distinct que nous exploitons. Chaque enregistrement ne porte que l’identifiant créateur de l’installation, une clé publique ; jamais votre compte. Une part configurable des installations est échantillonnée (par type de donnée et au total), décidée sur l’appareil : une installation hors échantillon n’envoie rien de ce type. Depuis les réglages de votre compte, vous pouvez demander l’export de tout ce qui est détenu sous un identifiant créateur lié à votre compte, ou son effacement ; la confirmation et l’export vont à l’adresse de votre compte et nulle part ailleurs, et une installation liée à un compte ne peut pas les diriger ailleurs. La demande, son état et son issue sont journalisés.'],
      ['Clé créateur BMM et empreinte de l’appareil', 'BMM identifie une installation par son identifiant créateur, une clé publique. Depuis la version 5 de cette clé, quand BMM nous prouve son identifiant créateur (quand vous envoyez un rapport de bug ou de plantage, quand vous liez l’application à un compte, et une fois par clé tant que l’application est liée à un compte), la preuve porte aussi une empreinte de l’appareil : quatre hachages à sens unique, calculés sur votre ordinateur, (1) des identifiants de la carte mère, du BIOS et du processeur, (2) des identifiants de l’installation Windows, (3) des identifiants du disque, et (4) de la façon dont votre carte graphique dessine une image de test fixe, appelé hachage canvas. Aucun numéro de série, aucune image et aucune valeur brute ne sont jamais envoyés, et chaque hachage est salé avec l’adresse de ce site : il ne peut pas être recoupé avec ce que reçoit un autre service.\n\nCe que nous en faisons : pour chaque identifiant créateur, nous conservons chaque hachage, le nombre de fois où il a été vu et quand. Les modérateurs s’en servent pour savoir si un nouvel identifiant créateur vient du même ordinateur qu’un identifiant banni ou ayant déjà utilisé une offre gratuite. Une personne décide toujours ; aucune règle n’agit automatiquement sur une correspondance. L’empreinte canvas est une technique de pistage et nous la nommons ainsi : elle sert uniquement à cette lutte contre les abus, jamais aux statistiques, à la publicité ni au profilage, et elle n’est jamais partagée.\n\nBase légale : notre intérêt légitime à empêcher l’abus des offres gratuites et le contournement des bannissements (art. 6, par. 1, let. f RGPD ; art. 31 nLPD). Conservation : chaque hachage est supprimé 180 jours après sa dernière apparition ; l’association entre une clé et un identifiant créateur est conservée tant que l’identifiant est utilisé. Ces hachages identifient un appareil, ce sont donc des données personnelles : vous pouvez en demander l’accès ou l’effacement, ou vous y opposer, via la page Contact, comme pour le reste de vos données.'],
      ['Vos droits (RGPD)', 'Vous pouvez demander l’accès, la rectification ou la suppression de vos données à tout moment en nous contactant. Supprimer votre compte efface vos données personnelles et dépublie votre contenu. Quelques enregistrements sont conservés, ou expirent selon leur propre délai ; la section Conservation les liste.'],
      ['Conservation', 'Combien de temps chaque chose est conservée, dans les délais que le service applique réellement plutôt qu’en promesse générale :\n\n· VOTRE COMPTE ET SON CONTENU — tant que le compte est ouvert. Le fermer programme la suppression à 30 JOURS, et le rouvrir dans ces 30 jours l’annule.\n· SESSIONS DE CONNEXION — jusqu’à expiration ou déconnexion. L’enregistrement d’une session révoquée est supprimé 30 JOURS plus tard.\n· ACCÈS AUX DÉPÔTS ET CATALOGUES — 30 JOURS, et au plus les 5000 derniers événements par dépôt ou catalogue.\n· STATISTIQUES — agrégées en compteurs journaliers. Par défaut, les événements sous-jacents sont conservés 365 JOURS pour les pages vues, 120 jours pour les clics et mesures de performance, 90 jours pour les rapports d’erreur et 30 jours pour les enregistrements de session. Un administrateur peut changer ces délais.\n· TENTATIVES DE CONNEXION — 180 JOURS par défaut. ALERTES DE CONNEXION — 180 JOURS.\n· JOURNAL DES E-MAILS ENVOYÉS — 90 JOURS, et au plus les 20 000 dernières entrées.\n· HACHAGES D’EMPREINTE D’APPAREIL BMM — 180 JOURS après leur dernière apparition.\n· RETOURS ET RAPPORTS DE PLANTAGE — pièces jointes 90 JOURS ; un rapport résolu ou ignoré 365 JOURS après sa dernière modification. Ce sont deux valeurs par défaut qu’un administrateur peut changer.\n· INSCRIPTIONS NON CONFIRMÉES — supprimées après 14 JOURS, sauf si le compte possède déjà quelque chose.\n· SIGNALEMENTS, NOTIFICATIONS ET DÉCISIONS DE MODÉRATION — conservés avec leur issue. C’est ainsi qu’un récidiviste est identifié et que nous pouvons montrer ce que nous avons fait et pourquoi.\n· PIÈCES DE PAIEMENT ET DE FACTURATION — 10 ANS, durée de conservation qu’impose le droit comptable suisse aux pièces commerciales.\n· SAUVEGARDES — 14 JOURS. C’est le délai qui compte après une suppression, il a donc sa propre ligne plutôt que d’être laissé à deviner.\n\nSupprimer votre compte atteint nos sauvegardes de deux façons différentes, et prétendre le contraire serait la moitié confortable de la vérité. L’historique ligne à ligne que le site conserve pour annuler une modification administrative est chiffré avec une clé propre à VOTRE compte ; effacer le compte détruit cette clé, donc ces instantanés deviennent illisibles pour tout le monde — y compris dans une copie déjà détenue ailleurs — tandis que ceux des autres restent intacts. Les sauvegardes complètes de la base, prises pour la reprise après sinistre, sont une copie figée de tout ce qui existait le jour où elles ont été prises : un compte effacé aujourd’hui se trouve encore dans une sauvegarde d’hier, et il y reste jusqu’à ce que celle-ci ait 14 jours et soit supprimée. Si nous devions en restaurer une, les effacements intervenus depuis sa prise sont réappliqués avant que le site ne resserve qui que ce soit — restaurer une ancienne copie n’est pas un moyen d’annuler une suppression.\n\nLorsqu’une obligation légale nous impose de conserver quelque chose plus longtemps que ci-dessus, cette obligation l’emporte, et elle est la seule à le faire.'],
      ['Fermer votre compte, et revenir', 'Une fermeture est planifiée 30 jours à l’avance et reste annulable pendant tout ce mois. Ce qui se produit au terme est une ANONYMISATION, pas une suppression de ligne : votre e-mail, votre nom affiché, votre profil et vos identifiants sont effacés, tandis que ce qui doit survivre à un compte — les factures, et l’historique de modération attaché à ce que vous avez publié — est conservé, parce que ce sont des enregistrements sur des transactions et des décisions, pas sur votre profil. Une chose conservée dérive de votre e-mail : un hachage à sens unique de l’adresse, et rien d’autre. Il existe pour que, si vous recréez un compte avec la même adresse, nous puissions vous reconnaître et rattacher votre historique — y compris un éventuel dossier de modération. Nous le disons franchement plutôt que de l’enfouir, parce que cela coupe dans les deux sens : un membre qui revient retrouve ce qu’il avait, et fermer un compte n’est pas un moyen de laisser une sanction derrière soi. S’inscrire avec une autre adresse repart vraiment de zéro. Ce hachage ne peut pas être retransformé en votre adresse, et ne sert à rien d’autre.'],
      ['Sécurité', 'Nous protégeons vos données par des mesures précises, pas seulement par une promesse de moyens « raisonnables ». Les mots de passe sont hachés avec argon2id et ne sont jamais stockés ni journalisés en clair ; l’authentification à deux facteurs est disponible sur chaque compte et requise pour l’accès du personnel et de l’administration. Le trafic passe en HTTPS et la base de données n’est pas exposée à Internet. Nous ne stockons PAS vos données de carte — les paiements passent par Stripe, qui les détient. Les actions privilégiées du personnel sont écrites dans un journal d’audit inviolable à chaînage de hachage, dont l’intégrité peut être vérifiée. Le trafic abusif est ralenti et bloqué automatiquement (limites de débit, un bouclier automatique, et des bannissements d’adresse/user-agent/créateur), et une politique de sécurité du contenu (CSP) limite ce qui peut s’exécuter dans votre navigateur. Les dépôts peuvent être protégés par un mot de passe ou une clé signée, et le contenu que vous hébergez est servi via la même bordure chiffrée. Nous prenons une sauvegarde quotidienne et pouvons restaurer le service à partir d’elle. Aucun système n’est parfaitement sûr ; en cas de violation vous concernant significativement, nous vous préviendrons et, si la loi l’exige, l’autorité de contrôle sous 72 heures (voir « En cas de violation de données »).'],
      ['Âge', 'BetterCommunity ne s’adresse pas aux enfants. Dans l’UE et l’EEE, il faut avoir au moins 16 ans, âge fixé par l’article 8 du RGPD — sauf si le pays où vous résidez l’a abaissé, ce que certains ont fait, sans pouvoir descendre sous 13 ans. Partout ailleurs, le minimum est de 13 ans. En cas de doute, c’est 16.'],
      ['Dons via Ko-fi', 'Les dons se font sur Ko-fi, pas ici : votre paiement relève entièrement des conditions et de la politique de confidentialité de Ko-fi, et nous ne voyons jamais votre carte.' + '\n\nCe qui nous parvient, en revanche, c’est une notification de Ko-fi pour chaque don, et nous la conservons : le NOM AFFICHÉ sous lequel vous avez donné, l’ADRESSE E-MAIL que Ko-fi transmet lorsque vous l’avez fournie, le montant et la devise, le caractère ponctuel ou mensuel du don, et la date. Nous les conservons pour reconnaître les soutiens, répondre aux questions relatives à un paiement, et parce qu’il s’agit d’une pièce comptable. Si l’e-mail transmis par Ko-fi est l’adresse d’un compte ici, ce compte reçoit un code de réduction d’hébergement unique et l’éventuel badge de soutien Ko-fi. La barre d’objectif du site n’affiche qu’un total et le nombre de dons, jamais un nom.' + '\n\nC’est le seul cas où nous pouvons détenir des données sur une personne qui n’a jamais créé de compte. L’article 14 du RGPD est la raison pour laquelle cela figure ici plutôt que d’être sous-entendu. Vous pouvez en demander l’effacement via la page Contact, sous la seule réserve des durées de conservation que le droit comptable impose aux justificatifs d’encaissement.'],
      ['Sous-traitants', 'Voici tous ceux qui reçoivent des données du fait de ce service. Chacun sert à une seule chose et à rien d’autre.\n\n· STRIPE — les paiements, et les reversements aux vendeurs de la marketplace. Les données de carte vont chez Stripe et jamais chez nous. Si vous VENDEZ sur une marketplace, vous ouvrez en outre votre propre compte Stripe via nous : les données d’identité et bancaires que Stripe exige pour vous payer vont directement chez Stripe, et nous ne voyons que l’état d’activation de ce compte et ce que Stripe attend encore de lui.\n· KO-FI — les dons. Ko-fi nous signale chacun d’eux ; ce qu’il transmet est décrit plus haut.\n· GOOGLE — la connexion, si vous choisissez « Continuer avec Google », et la liaison d’une chaîne YouTube, si vous le choisissez. Séparément, et uniquement avec votre consentement aux statistiques, un tag Google.\n· GITHUB — la connexion, si vous choisissez « Continuer avec GitHub ».\n· DISCORD — la connexion, la liaison de compte, et notre bot communautaire.\n· STEAM et TWITCH — la liaison de ces comptes à votre profil, si vous le choisissez.\n· YOUTUBE — uniquement les vidéos intégrées, chargées depuis youtube-nocookie.com, et seulement sur une page qui en contient une.\n· NOTRE HÉBERGEUR ET STOCKAGE OBJET — les serveurs et les fichiers eux-mêmes.\n· NOTRE SERVICE D’ENVOI D’E-MAILS — achemine les e-mails que ce site envoie.\n\nDeux choses qui ne sont PAS des sous-traitants : votre localisation approximative est cherchée dans une base de données sur notre propre serveur, donc votre adresse IP n’est pas envoyée à un service de géolocalisation ; et notre serveur consulte la page d’état publique de Stripe pour savoir si les paiements fonctionnent, une requête qui ne porte rien sur vous.\n\nSe connecter avec Google, GitHub ou Discord est facultatif et jamais imposé : une adresse e-mail et un mot de passe fonctionnent partout où ils fonctionnent. En choisir un indique à ce fournisseur que vous vous êtes connecté ici. Chacun ne reçoit que les données nécessaires à sa fonction et est lié par un accord de traitement.{{dpa}}'],
      ['Demandes Make Your Own', 'Si vous utilisez le service payant « Make Your Own », nous stockons les informations que vous soumettez (nom du produit, objectif, description et l’URL de logo éventuelle), la conversation avec notre équipe, les fichiers échangés et les enregistrements de paiement. Cela inclut les devis que nous vous envoyons et les fichiers que nous livrons. Nous les utilisons uniquement pour fournir le service. La conversation est lisible par le membre de l’équipe à qui la demande est assignée et par les administrateurs — pas par les autres membres, et jamais publiquement. Ne mets pas les données personnelles d’autrui dans une demande sans base légale. Deux choses à savoir avant d’en ouvrir une : un dossier de commande est un document FINANCIER, il est donc conservé quand vous fermez votre compte, contrairement à la plupart de vos données (même règle que les factures — le profil est anonymisé, pas la trace de la transaction) ; et tout fichier que vous joignez ou que nous livrons reste dans la conversation aussi longtemps que le dossier, donc envoyez un lien plutôt qu’une pièce jointe si vous préférez qu’il n’y reste pas. Un fichier livré est conservé 30 jours après la livraison, ou 7 jours après votre premier téléchargement, au premier des deux ; votre premier téléchargement est consigné (qui, quand) dans la conversation comme preuve de livraison. L’archivage d’une demande supprime ses pièces jointes et fichiers livrés et conserve les messages.'],
      ['Bases légales (RGPD Art. 6)', 'Nous traitons vos données sur ces bases : l’exécution de notre contrat (compte, hébergement, paiements) ; votre consentement (statistiques optionnelles, liaison Discord) ; nos intérêts légitimes (sécurité, prévention des abus, amélioration du service) mis en balance avec vos droits ; et le respect de nos obligations légales. Vous pouvez retirer votre consentement à tout moment sans affecter les traitements antérieurs.'],
      ['Enregistrement de session (désactivé sauf activation)', 'Indépendamment des compteurs ci-dessus, et uniquement avec le même consentement analytique, ce site peut enregistrer une RELECTURE d\u2019une visite \u2014 une reconstruction de ce à quoi la page ressemblait et de ce qui a été cliqué, rejouable comme une vidéo. C\u2019est désactivé par défaut et activé délibérément par un administrateur ; tant que c\u2019est désactivé, rien n\u2019est enregistré et rien n\u2019est stocké.\n\nCe que cela ne contient jamais, par construction et non par promesse : les valeurs que vous tapez. Les champs sont masqués au moment où l\u2019enregistrement est créé, donc un mot de passe, une adresse ou un message n\u2019existe jamais dans l\u2019enregistrement \u2014 il n\u2019y a rien à retirer ensuite. Les pages de connexion, de double authentification et de réglages ne sont jamais enregistrées. Un enregistrement est rattaché au même identifiant anonyme à rotation quotidienne que le reste de l\u2019analytique : il ne peut donc pas être relié à votre compte ni suivi d\u2019un jour à l\u2019autre.\n\nLes enregistrements ne sont conservés que dans une petite fenêtre glissante \u2014 les plus anciens sont supprimés à mesure que de nouveaux arrivent \u2014 et seuls les membres du staff disposant de la permission analytique peuvent en ouvrir un. Refuser la catégorie analytique, ou ignorer la bannière, signifie qu\u2019aucun enregistrement de votre visite n\u2019est jamais réalisé.'],
      ['Transferts internationaux', 'Certains sous-traitants (ex. Stripe, ou un tag analytics/Google si vous l’actives) peuvent traiter des données hors de votre pays, y compris hors EEE/Royaume-Uni. Le cas échéant, les transferts reposent sur des garanties appropriées comme les Clauses Contractuelles Types de l’UE ou une décision d’adéquation.'],
      ['Vos droits & comment les exercer', 'Au titre du RGPD, vous pouvez accéder à vos données, les rectifier, les effacer, en limiter ou vous opposer au traitement, retirer votre consentement et demander leur portabilité. Contactez-nous via la page Contact ; nous répondons sous un mois. Vous avez aussi le droit d’introduire une réclamation auprès de votre autorité de protection des données (en France, la CNIL).'],
      ['Pas de décision automatisée', 'Nous ne procédons à aucune décision automatisée ni profilage produisant des effets juridiques ou significatifs à votre égard.'],
      ['En cas de violation de données', 'Si des données personnelles font l’objet d’une violation susceptible d’engendrer un risque pour vos droits et libertés, nous notifions l’autorité de contrôle compétente dans les 72 HEURES après en avoir pris connaissance, comme l’exige l’article 33 du RGPD — et si un retard est inévitable, nous en donnons la raison.\n\nSi le risque pour vous est ÉLEVÉ, nous vous en informons aussi directement et sans délai injustifié : ce qui s’est passé, quelles données sont concernées, ce que nous pensons que cela signifie pour vous, et ce que nous faisons. Nous n’attendrons pas d’être certains de la cause pour vous prévenir, parce qu’un avertissement partiel et précoce vous est plus utile qu’un avertissement complet et tardif.\n\nLa loi fédérale suisse sur la protection des données impose une obligation parallèle d’annonce au Préposé fédéral à la protection des données et à la transparence, à laquelle nous satisfaisons de la même manière.'],
      ['Protection des données suisse (LPD), en plus du RGPD', 'Nous sommes établis en Suisse, donc la loi fédérale révisée sur la protection des données (nLPD, RS 235.1) nous est directement applicable. Le RGPD s’applique en plus, parce que nous offrons ce service à des personnes dans l’UE et l’EEE.\n\nLes deux régimes vous donnent en substance les mêmes droits — accès, rectification, effacement, opposition, portabilité — et nous n’exploitons pas deux procédures différentes. Exercez-les de la même façon, via la page Contact. La Suisse bénéficie d’une décision d’adéquation de la Commission européenne, donc les données qui nous parviennent de l’UE n’ont pas besoin d’un mécanisme de transfert séparé.\n\nL’autorité à saisir dépend de où vous êtes : en Suisse, le Préposé fédéral à la protection des données et à la transparence (PFPDT) ; dans l’UE ou l’EEE, votre autorité de contrôle locale. L’une comme l’autre peut être saisie sans passer par nous.'],
      ['Responsable de traitement & contact', 'Le responsable de traitement est l’opérateur de BetterCommunity. Pour toute demande — accès, suppression, portabilité, ou retrait de consentement — contactez-nous via la page Contact.'],
    ] },
    terms: { icon: ShieldCheck, title: 'Conditions d’utilisation', body: [
      ['Comptes', 'Vous êtes responsable de l’activité de votre compte et du contenu que vous soumettez. Gardez vos identifiants en sécurité.'],
      ['Contenu & modération', 'Les soumissions sont vérifiées avant publication. Nous pouvons refuser ou retirer tout contenu illégal, malveillant, contrefaisant ou contraire aux présentes conditions. Vous restez propriétaire de ce que vous envoyez et nous accordes une licence pour l’héberger et le distribuer sur la plateforme.'],
      ['Délais de vérification & validation', 'Chaque soumission et mise à jour passe en revue manuelle et reste masquée (EN ATTENTE) jusqu’à approbation par un administrateur. Nous visons une revue sous 72 heures, sans délai garanti, et cela peut être plus long en cas de forte affluence. Les fichiers de plugins/thèmes et le contenu des dépôts hébergés sont re-vérifiés automatiquement (SHA / checksums par fichier) à chaque changement et doivent être valides avant mise en ligne. Nous pouvons re-vérifier, re-valider ou dépublier un contenu déjà approuvé à tout moment.'],
      ['Droits d’auteur & règles de contenu hébergé', 'Vous ne pouvez héberger ou envoyer que du contenu que vous possédez ou que vous êtes autorisé à distribuer. Sont strictement interdits : le matériel sous droits d’auteur sans autorisation, les ressources tierces payantes ou fuitées, les logiciels malveillants ou charges obscurcies, les contenus illégaux, et tout ce qui porte atteinte à une marque ou aux droits d’un autre créateur. Les Dépôts Serveur hébergés doivent respecter les licences des créateurs d’origine.'],
      ['Ce dont nous sommes, et ne sommes pas, responsables', 'BetterCommunity est un service d’hébergement et de distribution. Le contenu qui s’y trouve — mods, catalogues, dépôts, thèmes, plugins, commentaires, fichiers — est envoyé par ses utilisateurs, et la personne qui l’a envoyé en est responsable. Nous ne filtrons pas les envois a priori et n’avons pas d’obligation générale de surveillance ; nous agissons sur ce qui nous est signalé et sur ce que nous constatons. Les listes curées ou « officielles » sont l’exception dans un seul sens : relire un élément signifie que nous l’avons regardé, pas que nous le garantissons, et ça ne fait pas de nous son auteur. Rien ici ne limite une responsabilité qui ne peut légalement pas l’être — y compris notre propre fraude, ou un décès ou dommage corporel causé par notre négligence.'],
      ['Les fiches qui pointent ailleurs', 'Une grande partie de ce qui est référencé ici est un LIEN, pas un fichier. Une entrée de dépôt, un élément de catalogue ou une source peut pointer vers GitHub, vers le serveur d’un créateur, vers un Server-Repo que nous n’exploitons pas. Pour ceux-là nous stockons la fiche — un nom, une description, une icône, une URL — et rien d’autre. Le fichier lui-même ne touche jamais nos machines.\n\nIl s’agit d’une limite à ce qu’un signalement adressé à nous peut obtenir. Quand une fiche pointe ailleurs, tout ce que nous pouvons faire est de notre côté du lien :\n\n· retirer la fiche, pour que ce service cesse d’y envoyer qui que ce soit ;\n· empêcher l’URL ou le domaine d’être référencé à nouveau ;\n· agir contre le compte qui l’a publiée, jusqu’à la fermeture.\n\nCe que nous NE POUVONS PAS faire, c’est supprimer le fichier, le modifier, ou le rendre indisponible à quelqu’un qui en a déjà l’adresse. Il ne nous appartient pas et il n’est pas ici. Si vous êtes ayant droit et que vous ne le signalez qu’à nous, le contenu demeure accessible, car le déréférencement retire la référence et non son objet. La notification doit également être adressée à la partie qui héberge effectivement le fichier ; lorsque celle-ci est identifiable, nous indiquons qui elle semble être, sans garantir l’exactitude de cette identification.\n\nNous déréférençons sur signalement fondé sans déterminer au préalable si le fait de lier engage notre responsabilité. Stocker un contenu et y renvoyer sont des actes distincts au regard du DSA, de la LCEN et du droit suisse, mais cette question relève du juge et nous n’en faisons pas un motif de différer notre action. Le contenu que nous hébergeons nous-mêmes relève des sections ci-dessus ; celle-ci ne concerne que le reste.'],
      ['Quelle loi s’applique à un signalement', 'Ce service est exploité depuis la Suisse et soumis au droit suisse, hébergé en France, et utilisé depuis partout. Plusieurs régimes peuvent donc s’appliquer à un même signalement, alors les voies sont exposées séparément plutôt que fondues en une seule qui n’irait à personne :\n\n· TOUT contenu illégal ou contrefaisant — le système de signalement ci-dessous. Une voie, une file, lue par une personne. À utiliser en cas de doute, c’est-à-dire la plupart du temps.\n· CONTENU ILLÉGAL, depuis l’UE — la même voie, construite pour satisfaire l’article 16 du Règlement sur les services numériques (DSA, règlement (UE) 2022/2065), afin qu’une notification qui y transite nous donne aussi connaissance effective en droit de l’UE.\n· CONTENU HÉBERGÉ EN FRANCE — le formalisme LCEN ci-dessous. Il n’est pas obligatoire, mais une notification sous cette forme est ce qui nous rend légalement présumés informer, ce qui déclenche notre obligation d’agir.\n· DROIT D’AUTEUR, où que vous soyez — le même mécanisme de notification. Le droit d’auteur est une forme d’illégalité, pas une file séparée, et une voie qui fonctionne vaut mieux que deux qui fonctionnent à moitié.\n· DROIT D’AUTEUR, en droit suisse — la section suisse ci-dessous, qui ajoute une obligation que les autres n’ont pas.\n\nNous n’exploitons pas de procédure DMCA américaine de notification et contre-notification et ne revendiquons aucune protection au titre du §512 — nous n’y sommes pas établis. Une réclamation de droit d’auteur venant des États-Unis est traitée par le mécanisme ci-dessus, comme toute autre.\n\nIl n’est pas nécessaire de déterminer de quel régime vous relevez. Envoyez ce que vous avez via la page Contact en disant ce qui ne va pas et où ; nous le traiterons sous le régime qui lui donne effet. Ces formalismes existent parce qu’en utiliser un vous donne une position juridique plus forte, pas parce que nous vous ignorerions sinon.'],
      ['Comment fonctionne le système de signalement', 'La procédure comporte quatre étapes.\n\n1. SIGNALER. N’importe qui peut nous signaler un contenu qu’il estime illégal ou contrefaisant, via la page Contact ou le bouton de signalement à côté du contenu. Aucun compte n’est nécessaire pour signaler.\n2. AYANTS DROIT. Si vous détenez un droit, indiquez quelle œuvre, où elle se trouve sur ce service, et à quel titre vous la détenez. Cela suffit pour que nous agissions. Les exigences formelles propres à certains régimes juridiques sont exposées dans les sections ci-dessous.\n3. EXAMINER ET AGIR. Une personne le lit — aucune décision automatisée. Si c’est clair, nous retirons ou désactivons le contenu et informons celui qui l’a publié, avec les motifs et la manière de contester. Lorsque la situation n’est pas claire, nous le disons. Nous ne sommes pas un tribunal et ne pouvons pas trancher des prétentions concurrentes de propriété.\n4. EMPÊCHER LE RETOUR. Un contenu retiré après signalement est empêché d’être remis en ligne via ce service, dans la limite de ce que nous pouvons techniquement et raisonnablement faire. La section suivante dit précisément quand le droit suisse en fait une obligation plutôt qu’une politique.\n\nChaque signalement est enregistré avec l’issue qui lui a été donnée.'],
      ['Notification et action (UE — article 16 du DSA)', 'N’importe qui, où qu’il soit, peut nous signaler un contenu qu’il estime illégal. Envoyez-le via la page Contact. Selon l’article 16(2), une notification requiert quatre éléments, et une notification qui les contient nous donne CONNAISSANCE EFFECTIVE du contenu — c’est tout l’intérêt d’en envoyer une :\n\n1. Une explication motivée des raisons pour lesquelles vous estimez le contenu illégal.\n2. La localisation électronique exacte : une URL, ou le nom du dépôt / catalogue / élément et le chemin du fichier à l’intérieur.\n3. Vos nom et adresse e-mail. (Non requis pour les signalements portant sur les infractions visées aux articles 3 à 7 de la directive 2011/93/UE.)\n4. Une déclaration attestant que vous croyez de bonne foi que ce que vous avancez est exact et complet.\n\nCe que nous faisons : nous accusons réception, décidons sans retard injustifié, et vous informons de l’issue. Si nous retirons ou restreignons un contenu, la personne qui l’a publié reçoit un exposé des motifs — ce qui a été fait, pourquoi, sur quelle base légale ou contractuelle, et comment le contester. Nous n’utilisons pas de décision automatisée pour cela ; une personne lit chaque signalement.'],
      ['Nous notifier en droit français (LCEN)', 'Notre hébergement est en France, la loi pour la confiance dans l’économie numérique (LCEN, n° 2004-575 du 21 juin 2004) vous est donc ouverte. L’article 6-I-2 signifie que nous ne sommes pas responsables de ce que les utilisateurs stockent ici à moins d’avoir effectivement eu connaissance de son caractère illicite et de ne pas avoir agi promptement ; l’article 6-I-7 signifie que nous n’avons pas d’obligation générale de surveillance.\n\nUne notification au sens de l’article 6-I-5 emporte présomption de connaissance, et doit pour cela indiquer :\n\n1. La date de la notification.\n2. Si vous êtes une personne physique : vos nom, prénoms, profession, domicile, nationalité, date et lieu de naissance. Si personne morale : sa forme, sa dénomination, son siège social et l’organe qui la représente légalement.\n3. Nos nom et domicile en tant que destinataire.\n4. La description des faits litigieux et leur localisation précise.\n5. Les motifs pour lesquels le contenu doit être retiré, comprenant la mention des dispositions légales et des justifications de faits.\n6. La copie de la correspondance adressée à l’auteur ou à l’éditeur demandant l’interruption, le retrait ou la modification — ou la justification de ce que vous n’avez pas pu le joindre.\n\nLe point 6 est fréquemment omis. Le droit français exige que l’auteur ou l’éditeur ait d’abord été sollicité, ou que la tentative soit établie.\n\nEnfin, l’article 6-I-4 fait un DÉLIT PÉNAL, puni d’un an d’emprisonnement et de 15 000 € d’amende, du fait de présenter un contenu comme illicite afin d’en obtenir le retrait en sachant cette information inexacte. C’est nettement plus tranchant que son équivalent américain.'],
      ['Droit d’auteur en droit suisse (LDA, RS 231.1)', 'Le droit suisse ne prévoit ni procédure générale de notification et retrait, ni forme de notification imposée. L’article 39d de la loi sur le droit d’auteur institue une obligation spécifique et de portée étroite, reproduite ci-après dans sa substance.\n\nUn fournisseur d’hébergement doit empêcher qu’une œuvre soit à nouveau mise à disposition illicitement via son service lorsque LES TROIS conditions suivantes sont réunies :\n\na. l’œuvre a déjà été mise à disposition illicitement via LE MÊME service ;\nb. le fournisseur A ÉTÉ INFORMÉ de cette atteinte ; et\nc. le service a créé un RISQUE PARTICULIER de telles atteintes, notamment par un mode de fonctionnement technique ou une orientation économique qui favorise les atteintes.\n\nL’alinéa 2 limite cela aux mesures techniques et économiques que l’on peut raisonnablement attendre, en proportion de ce risque. L’article 62 alinéa 1bis fait d’un manquement à l’article 39d une atteinte dont un ayant droit peut saisir le juge.\n\nLa condition (c) commande l’existence même de l’obligation et vise les services dont la conception ou l’orientation commerciale favorise les atteintes. Nous ne considérons pas que ce service en relève et ne prétendons pas que l’article 39d nous soit applicable. Nous empêchons néanmoins la remise en ligne des contenus retirés, au titre d’une politique interne et non d’une obligation légale.\n\nUne autre règle suisse, hors droit d’auteur : l’article 28a du Code civil permet d’agir contre quiconque PARTICIPE à une atteinte aux droits de la personnalité, et la jurisprudence suisse a admis qu’un hébergeur puisse être un tel participant. C’est pourquoi les plaintes pour vie privée et usurpation d’identité sont traitées directement, plutôt que renvoyées pour être reformulées en droit d’auteur.\n\nLà où aucune loi ne prescrit autre chose, nous suivons la pratique de notification et retrait du Code of Conduct Hosting de la SIMSA, le standard suisse du secteur.'],
      ['Comment nous joindre, et comment les autorités nous joignent', 'Un point de contact électronique unique sert à tout le monde : la page Contact. Ce n’est pas un système automatisé — une personne lit ce qui y arrive — et c’est l’adresse à utiliser pour un signalement, une contestation de décision, une notification d’ayant droit ou une demande relative aux données.\n\nLes autorités des États membres, la Commission européenne et le Comité européen des services numériques utilisent la même adresse, de même que les autorités suisses et françaises. Aucune demande officielle n’a besoin d’un canal différent, et nous n’en exigeons aucun.\n\nNous travaillons en FRANÇAIS et en ANGLAIS. Une notification dans l’une de ces langues est traitée sans traduction ; dans une autre langue elle est traitée aussi, mais plus lentement et avec un risque de perte au passage — utilisez l’une des deux si vous le pouvez.'],
      ['Comment nous modérons, dit à l’avance', 'Ce qui suit est toute la politique, pour qu’aucun retrait ne soit une surprise. L’article 14 du DSA exige qu’elle figure ici, et non qu’elle se découvre après coup.\n\nCE SUR QUOI NOUS AGISSONS. Un contenu illicite, qui porte atteinte aux droits de quelqu’un, ou qui enfreint les règles d’usage acceptable ci-dessus. Aucun autre motif n’est retenu. Ni la désapprobation d’un contenu, ni le nombre de plaintes reçues à son sujet ne constituent un motif.\n\nQUI DÉCIDE. Une personne. Chaque soumission et chaque mise à jour est mise en file et reste masquée tant que quelqu’un ne l’a pas examinée, et chaque retrait, restriction, rétrogradation ou suspension est une décision humaine. Nous faisons tourner des mesures automatisées — filtres anti-bots en périphérie, heuristiques anti-spam et anti-abus, limites de débit — mais elles gardent l’accès au service ; elles ne décident pas si votre contenu reste en ligne.\n\nCE QUE NOUS POUVONS FAIRE. Refuser ou retirer un élément, le masquer le temps de l’examen, déréférencer un lien, restreindre sa visibilité, suspendre un compte ou le fermer. La mesure est choisie pour correspondre à ce qui ne va pas — nous retirons un élément plutôt qu’un compte, et un compte plutôt que tout ce qu’une personne a publié, sauf si le cas l’exige vraiment.\n\nAVEC QUEL ÉGARD. De manière diligente, objective et proportionnée, dans le respect des droits fondamentaux de tous les intéressés — y compris la liberté d’expression de celui qui a publié, ce qui explique que nous ne retirions pas sur simple injonction non motivée et que chaque décision soit accompagnée de ses motifs et d’une voie de recours.'],
      ['Quand nous prévenons la police', 'Si nous prenons connaissance d’informations faisant soupçonner qu’une infraction pénale impliquant une MENACE POUR LA VIE OU LA SÉCURITÉ d’une personne a été commise, est en cours ou est susceptible d’être commise, nous en informons les autorités répressives ou judiciaires de l’État membre concerné, ou Europol si aucun État membre n’est identifiable, et nous transmettons ce que nous savons. C’est l’article 18 du DSA et ce n’est pas discrétionnaire.\n\nC’est le seul cas où nous saisissons les autorités de notre propre initiative. Nous ne signalons pas les infractions ordinaires à nos règles, les litiges de droit d’auteur, ni les contenus que nous avons simplement retirés. Par ailleurs nous répondons aux injonctions légales des autorités — suisses, françaises ou d’un État membre de l’UE — et nous en informons l’utilisateur concerné, sauf si l’injonction ou la loi l’interdit.'],
      ['Contester notre décision (UE — articles 17, 20 et 21 du DSA)', 'Si nous retirons, restreignons, déclassé ou suspendons quelque chose qui vous appartient, vous recevez un exposé des motifs : ce que nous avons fait, pourquoi, si un signalement ou notre propre vérification l’a déclenché, si de l’automatisation est intervenue, et comment le contester.\n\nVous pouvez le contester auprès de nous, gratuitement, pendant au moins six mois après la décision — via la page Contact en citant la référence figurant dans la notification. Une personne le réexamine, autre que celle qui a décidé lorsque c’est possible, et nous revenons sur les décisions que nous avons mal prises.\n\nVous disposez d’AU MOINS SIX MOIS à compter de la décision pour la contester, et cela ne coûte rien. En cas de désaccord persistant, les utilisateurs de l’UE peuvent porter le litige devant un organe certifié de règlement extrajudiciaire au sens de l’article 21. Cela ne retire pas votre droit d’aller en justice, et rien d’autre sur cette page ne le retire non plus.\n\nL’abus vaut dans les deux sens. Nous suspendons les comptes qui publient de façon répétée des contenus manifestement illégaux, et nous cessons également de traiter les signalements de quiconque en envoie de façon répétée de manifestement infondés — après avertissement, dans les deux cas. Un canal de signalement utilisable comme arme est un canal qui cesse de fonctionner pour ceux qui en ont besoin.'],
      ['Récidive', 'Nous suspendons puis fermons les comptes des contrevenants récidivistes, comme l’article 23 du DSA nous l’impose. Chaque notification retenue compte pour un avertissement contre le compte qui a envoyé le contenu ; un recours que nous accueillons l’efface. Vous êtes averti avant une suspension, et informé de ce qui vous est reproché.\n\nCe n’est pas discrétionnaire — un service qui continue d’héberger pour quelqu’un qui continue de contrefaire perd la protection qui lui permet d’héberger quoi que ce soit. Une fermeture pour récidive n’est pas remboursée.'],
      ['Ce que nous publions, et ce dont nous sommes exemptés', 'BetterCommunity est exploité à l’échelle d’une micro-entreprise. L’article 19 du DSA nous exempte à ce titre des articles 20 à 22 — système interne de traitement des réclamations, règlement extrajudiciaire des litiges, priorité aux signaleurs de confiance — et l’article 15(2) nous exempte de publier des rapports annuels de transparence.\n\nNous mentionnons cette exemption plutôt que de nous en prévaloir en silence, car nous offrons l’essentiel de ce dont elle nous dispense. La voie de recours décrite dans « Contester notre décision » est réelle, gratuite, et nous l’honorerons ; le droit de saisir un organe extrajudiciaire certifié est décrit parce que les utilisateurs de l’UE en disposent face aux fournisseurs non exemptés et que nous ne voulons pas être la raison pour laquelle quelqu’un croit n’avoir aucun recours. Ce à quoi nous ne nous engageons PAS, c’est la priorité aux signaleurs de confiance, parce que nous ne pouvons pas promettre une file que notre volume ne permet pas de faire tourner.\n\nSi le service dépasse le seuil de l’exemption, ces obligations commencent à nous lier et cette section change avant, pas après.'],
      ['Marques, et tout ce qui n’est pas le droit d’auteur', 'Les plaintes pour marque, usurpation d’identité et atteinte à la vie privée passent par le même mécanisme de notification que le reste — il y a une seule file, et une personne la lit. Ce qui diffère, c’est ce que nous pouvons faire : nous ne sommes pas un tribunal et ne pouvons pas trancher à qui appartient un nom, donc pour une marque ou un droit de la personnalité nous agissons sur ce qui est clair et vous disons quand ça ne l’est pas. Envoyez-les via la page Contact en décrivant ce qui ne va pas et où. Un contenu illégal là où nous opérons est retiré dès constatation, sans attendre de notification.'],
      ['Hébergement', 'Les Server-Repos hébergés sont soumis aux limites de stockage, d’upload et de capacité que nous fixons. Les mises à jour exigent un SHA valide. Tout abus, contenu illégal ou usage excessif peut entraîner une suspension.'],
      ['Données & contenu que vous hébergez', 'Vous êtes seul responsable de tout ce que vous envoyez, hébergez ou distribuez via le service, y compris sa légalité et les données personnelles qu’il contient. Vous garantissez avoir le droit de le stocker et le partager, et sa conformité à toutes les lois applicables (protection des données et droit d’auteur inclus). Nous agissons uniquement comme hébergeur/stockage neutre et, lorsque votre contenu contient des données personnelles, comme votre sous-traitant agissant sur vos instructions — vous restez le responsable de traitement. Nous ne sauvegardons pas vos données hébergées à votre place ; gardez votre propre copie. Vous acceptez de nous garantir et de nous tenir indemnes de toute réclamation, perte ou responsabilité d’un tiers découlant du contenu ou des données que vous hébergez.'],
      ['Téléchargements & usage des logiciels et contenus — à vos risques', 'BetterCommunity vous permet de télécharger et d’utiliser les applications Better* (comme BMM, BSM et BetterInstaller) et le contenu soumis par la communauté (mods, plugins, thèmes, presets et Server-Repos hébergés). Tout cela est fourni « tel quel », sans aucune garantie d’adéquation, de sécurité, de compatibilité ou de résultat. Vous le téléchargez, l’installez et l’utilisez entièrement à vos propres risques. Dans la limite permise par la loi, nous n’assumons aucune responsabilité pour les conséquences du téléchargement ou de l’utilisation de quoi que ce soit obtenu via la plateforme — y compris dommages à votre appareil, votre système d’exploitation ou vos autres logiciels, perte ou corruption de fichiers, corruption de jeu ou de sauvegardes, incompatibilité, ou toute suspension, tout bannissement ou toute sanction infligés par un jeu, une boutique, un service ou un éditeur tiers. Vérifiez ce que vous installez et gardez vos propres sauvegardes.'],
      ['Contenu tiers & absence d’endossement', 'Le contenu communautaire est créé et publié par ses auteurs, pas par nous. Notre modération et nos contrôles d’intégrité automatiques visent à détecter les abus et malwares évidents, mais ils ne garantissent ni la sécurité, ni la qualité, ni la légalité, ni l’adéquation, et le fait de lister ou d’héberger un contenu ne vaut jamais approbation. Vous êtes seul responsable du respect des conditions, licences et règles de tout jeu, plateforme, mod loader ou logiciel tiers avec lequel vous utilisez ce contenu — certaines modifications peuvent enfreindre les conditions de ces tiers, et toute conséquence qui en découle (y compris un bannissement de compte sur ces services) vous incombe seul.'],
      ['Acceptation des présentes conditions', 'Vous devez accepter les présentes Conditions et la politique Paiements & Remboursements avant de pouvoir payer un hébergement ou une option. Nous enregistrons la date et l’heure de votre acceptation. En cas de changement important, une nouvelle acceptation peut être requise avant votre prochain achat.'],
      ['Travaux sur commande (Make Your Own)', 'Le service optionnel « Make Your Own » vous permet de payer des frais de consultation pour discuter d’un produit que vous souhaitez faire créer (par exemple un bot Discord, une application, un site web, ou un travail sur mesure comme une revue de sécurité de code) et recevoir un conseil ainsi qu’un devis écrit. Les frais de consultation paient ce conseil et le devis uniquement — ce n’est PAS le prix du produit, et aucune création ne démarre tant que vous n’avez pas validé et payé le devis séparé. Les délais sont des estimations, pas des garanties. Vous devez détenir les droits sur tout élément que vous fournissez (noms, logos, ressources et — pour une revue de sécurité — le code ou le système à examiner, dont vous confirmez être autorisé à demander l’analyse), et vous êtes responsable de la légalité et de l’usage prévu de ce que vous demandez ; nous pouvons refuser ou arrêter toute demande illégale, contrefaisante ou abusive. Le travail livré est fourni « tel quel » ; chaque devis indique s’il inclut le code source. Sauf mention contraire du devis, une fois le paiement intégral effectué vous obtenez le droit d’utiliser le produit livré pour l’usage décrit, tandis que nous conservons la propriété de nos outils, bibliothèques et savoir-faire préexistants. Les conclusions d’une revue de sécurité sont fournies au mieux et ne garantissent jamais l’absence de vulnérabilités. Les remboursements de ce service sont traités dans la politique Paiements & Remboursements.'],
      ['Devis (Make Your Own)', 'Un devis est une offre détaillée avec un total, une devise et une date de validité. C’est une offre, pas un contrat : tant que vous ne l’avez pas payé, chacun peut se retirer — vous pouvez le refuser, et nous pouvons le retirer (par exemple si votre demande change, si nos coûts changent, ou si nous ne pouvons plus prendre le travail). Passée sa date de validité, un devis ne nous engage plus et nous pouvons le réémettre à un autre prix. Payer un devis, c’est commander le travail, et ce que vous commandez est ce que ce devis décrit — tout ce qui en sort est un nouveau devis, pas une révision incluse. Un devis indique s’il inclut le code source ; quand ce n’est pas le cas, vous recevez le produit fonctionnel et nous conservons les sources. Les demandes marquées URGENT ont des frais de consultation plus élevés, affichés avant le paiement. Nous pouvons refuser une demande, ou suspendre les nouvelles quand la file est pleine — auquel cas aucun frais de consultation n’est prélevé.'],
      ['Paiements', 'L’hébergement, la mise en avant et les produits de la marketplace sont facturés via Stripe. Les prix sont affichés avant confirmation et peuvent changer avec préavis ; un changement n’affecte jamais une période déjà payée. Si vous demandez un remboursement en cours d’abonnement, la partie non utilisée est rendue au prorata (au jour près) et la période déjà consommée est déduite ; lorsque la faute est de notre fait (erreur de facturation ou panne de notre fait), nous remboursons intégralement la période concernée. Voir la politique Paiements & Remboursements pour le détail complet. Vendre sur une marketplace exige en outre votre propre compte Stripe, que nous vous aidons à ouvrir ; nous prenons une commission sur chaque vente et Stripe transfère le reste vers ce compte.'],
      ['Vendre sur une marketplace', 'Si vous mettez un produit en vente sur la marketplace d’un projet, les présentes conditions s’appliquent à vous en tant que vendeur, en plus de tout le reste.\n\nVous déclarez avoir le droit de vendre ce que vous mettez en vente et que sa page le décrit fidèlement. Vous êtes responsable du contenu lui-même — que la clé fonctionne, que le fichier soit bien ce qu’il annonce, et que le fournir à un acheteur ne porte atteinte au droit de personne. Nous pouvons retirer un produit, refuser une mise en vente, ou retenir un reversement si nous avons des motifs raisonnables de penser que ce n’est pas le cas, et nous vous en dirons la raison.\n\nNous prenons une commission sur chaque vente. Elle vous est indiquée avant votre mise en vente et ne change pas pour une vente déjà faite. Pour être payé, vous ouvrez un compte Stripe via nous et vous passez leurs vérifications ; ce compte est le vôtre, les conditions de Stripe le régissent, et tant que Stripe ne l’a pas activé vos ventes sont conservées par nous puis versées ensuite.\n\nNous sommes le vendeur d’enregistrement. L’acheteur nous paie et nous gérons les remboursements et les litiges, ce qui veut dire que nous pouvons décider de rembourser un acheteur sans votre accord — et quand nous le faisons, ou quand nous perdons un chargeback, nous récupérons le montant sur votre part. Si votre part n’y suffit pas, vous nous devez la différence.'],
      ['Échec de paiement & conservation des données', 'Si le paiement d’un abonnement d’hébergement échoue, vous disposez d’au moins 72 heures pour le renouveler (actuellement sept jours). Passé ce délai, les données stockées pour cet abonnement (fichiers de Server-Repo hébergés et contenu associé) sont supprimées sans préavis ni sauvegarde.'],
      // N-hosting (agent-hosting-N) : ce que garantit un terme prépayé, et ce qu’il ne garantit pas.
      ['Termes prépayés : ce à quoi nous nous engageons', 'Un terme d’hébergement peut être payé d’avance pour 1, 6 ou 12 mois ; rien de plus long n’est vendu. Pour le terme que vous avez payé, nous nous engageons à fournir la formule achetée (son stockage, son plafond de débit et les fonctions indiquées pour elle) jusqu’au dernier jour de ce terme. C’est tout l’engagement : nous ne promettons pas que le service, une formule ou un prix existeront encore après le terme payé, et rien dans ces conditions ne promet une disponibilité sur plusieurs années.\n\nSi nous arrêtons le service, ou une formule que vous avez prépayée, avant la fin de votre terme, nous vous prévenons à l’avance, par e-mail et dans votre compte ; votre contenu reste téléchargeable jusqu’à l’arrêt du service, et nous remboursons la partie non utilisée de votre terme prépayé, au prorata au jour près, sur le moyen de paiement d’origine, sans que vous ayez à le demander. Les termes de plus de 12 mois achetés avant ce changement sont honorés jusqu’à leur fin, aux mêmes conditions.\n\nUne remise pour être resté abonné (remise fidélité) ne s’applique qu’au renouvellement, comme le décrit la politique Paiements & Remboursements ; ce n’est la promesse d’aucun prix futur.'],
      ['Plans du bot Discord', 'Le bot Discord s’ajoute gratuitement à n’importe quel serveur. Certaines de ses fonctions, et certaines de ses limites (combien de panneaux de rôles, de salons vocaux, de mots bloqués, etc.), peuvent demander un plan du bot Discord payant, seul ou inclus dans un plan de stockage. Un plan est un abonnement mensuel qui s’applique aux serveurs que vous choisissez parmi ceux que vous possédez ou gérez, jusqu’au nombre que le plan couvre. Ce qu’un serveur reçoit sans plan est indiqué sur la page Hébergement et peut changer avec préavis. Quand un plan se termine, les réglages de votre serveur sont conservés, et les fonctions et limites ajoutées par le plan cessent de s’appliquer jusqu’à un nouvel abonnement. Nous pouvons cesser de servir un serveur qui enfreint ces conditions, quel que soit son plan.'],
      ['Usage acceptable', 'Vous vous engagez à ne pas abuser du service : pas de scraping ni d’accès automatisé massif au-delà de nos API documentées, pas de surcharge, pas de sondage de sécurité non autorisé, pas de contournement des quotas, du bac à sable ou des contrôles d’intégrité, et aucun envoi de malware, de charge obfusquée ou de contenu illégal. Nous pouvons limiter, brider, suspendre ou bloquer toute activité abusive à tout moment.\n\nIl n’y a délibérément aucune interdiction de rétro-ingénierie. Le code de cette plateforme est OUVERT, et le lire, s’en inspirer ou en faire tourner sa propre copie relève de sa licence et non de cette politique — une clause vous interdisant de comprendre un logiciel que nous publions serait à la fois incohérente et inopposable. Ce qui est interdit ci-dessus, c’est de s’attaquer au SERVICE EN FONCTIONNEMENT et à ceux qui l’utilisent, ce qui est tout autre chose.'],
      ['Application des règles', 'Nous appliquons ces conditions de manière stricte et à notre entière discrétion. Toute violation peut entraîner le retrait immédiat du contenu, la suspension ou la résiliation définitive de votre compte et de vos dépôts hébergés — sans préavis ni remboursement — et, lorsque la loi l’exige, un signalement aux autorités compétentes. Tenter de contourner la modération, les contrôles d’intégrité, les quotas ou le bac à sable constitue en soi une violation. Ces mesures sont cumulatives et s’ajoutent à tout autre recours dont nous disposons.'],
      ['Droit applicable & modifications', 'Ces conditions sont régies par le DROIT SUISSE, droit du lieu de notre établissement, sans égard aux règles de conflit de lois.\n\nCe choix ne déplace pas, et ne peut pas déplacer, trois choses. Si vous êtes consommateur, les protections impératives du pays où vous résidez continuent de s’appliquer — une clause de droit applicable ne peut pas vous les retirer. Le règlement sur les services numériques nous est applicable parce que nous offrons ce service dans l’UE, quel que soit notre établissement. Et les serveurs sont en France, ce qui place ce qui y est stocké à portée du droit et des tribunaux français, indépendamment de cette clause. En cas de conflit avec ce qui est écrit ici, ce sont eux qui l’emportent. Nous pouvons les mettre à jour ; les changements importants sont annoncés et la poursuite de l’utilisation vaut acceptation. Si une clause est jugée inapplicable, le reste demeure pleinement en vigueur.'],
      ['Avertissement & responsabilité', 'Le service est fourni « tel quel » et « selon disponibilité », sans garantie d’aucune sorte. Dans la limite permise par la loi, nous ne sommes pas responsables des dommages indirects ou accessoires, et notre responsabilité totale est limitée aux sommes que vous nous avez versées durant les 12 mois précédant la réclamation.'],
    ] },
    cookies: { icon: Cookie, title: 'Politique de cookies', body: [
      ['Ce que sont les cookies', 'Les cookies et technologies similaires (comme le stockage local) sont de petites données conservées dans votre navigateur. Nous les regroupons ci-dessous par finalité. Vous contrôlez les catégories optionnelles depuis la bannière cookies et peux changer votre choix à tout moment.'],
      ['Ce qui reste dans votre navigateur et n’est jamais envoyé', 'L’essentiel de ce que ce site retient à votre sujet ne quitte jamais votre appareil, et ça mérite d’être séparé de la question des cookies : rien de tout ça n’est une décision de suivi. Votre thème, votre langue, la transparence, la disposition, le fait que vous ayez passé l’intro, votre historique de notifications, vos brouillons de soumission et — si vous utilisez l’authentificateur intégré — vos secrets TOTP vivent dans le stockage local de votre navigateur. Rien ne nous est transmis, rien n’entre dans les statistiques, et effacer les données du site les supprime. L’authentificateur est le cas le plus net : il est conçu pour que ses secrets n’atteignent JAMAIS un serveur, et vous pouvez les chiffrer au repos avec une phrase secrète que vous seul connaissez. La contrepartie est honnête — ce que nous ne recevons jamais, nous ne pouvons pas vous le restaurer.'],
      ['1 · Strictement nécessaires', 'Un cookie de session vous garde connecté, jusqu’à 7 jours. Quelques autres servent à une seule tâche et expirent d’eux-mêmes : un de 15 minutes après que vous avez confirmé à nouveau votre identité pour une action sensible ; des cookies de 5 à 10 minutes qui rattachent une connexion ou une liaison de compte au navigateur qui l’a commencée ; un de 12 heures quand vous ouvrez le tableau de bord propriétaire d’un dépôt ; et un de 4 heures sur le tableau de bord de télémétrie. Ils sont indispensables à ces fonctions et ne peuvent être désactivés. Selon le RGPD/ePrivacy, aucun consentement n’est requis pour cette catégorie car elle est essentielle à un service que vous avez demandé.'],
      ['2 · Statistiques (optionnel — désactivé par défaut)', 'Uniquement si vous acceptez la catégorie Statistiques, nous activons des statistiques internes respectueuses de la vie privée : chemin de page et référent, un hachage de visiteur anonyme changeant chaque jour, appareil / navigateur / système approximatif, localisation approximative (pays / région / ville) depuis votre IP, signaux d’interaction anonymes dans la page (quels éléments sont cliqués/édités/soumis — jamais les valeurs saisies), et mesures de performance (Web Vitals). Votre choix est mémorisé dans le stockage local, pas dans un cookie de pistage, et vous pouvez refuser sans perte de fonctionnalité.'],
      ['Tags tiers (Google Tag Manager)', 'Quand il est configuré, nous chargeons Google Tag Manager comme tag de mesure tiers. Ses scripts et cookies ne se chargent QU’APRÈS votre opt-in à la catégorie Statistiques ci-dessus — jamais avant. Refuser, ou simplement ignorer la bannière, le garde désactivé. Google agit comme notre sous-traitant ; certaines données peuvent être transférées hors EEE sous garanties appropriées (voir la Politique de confidentialité). Vous pouvez retirer votre consentement à tout moment.'],
      ['Gérer votre consentement', 'Votre préférence est stockée par navigateur. Pour la changer, utilisez le réglage des cookies dans la page Paramètres, ou videz le stockage de ce site et rechargez la page pour que la bannière réapparaisse. Retirer le consentement arrête aussitôt nos propres statistiques ; un tag Google déjà chargé s’arrête au prochain rechargement de la page.'],
      ['Aucune publicité', 'Nous n’utilisons jamais de cookies publicitaires, inter-sites ou de pistage social, et nous ne vendons jamais vos données.'],
    ] },
    about: { icon: Sparkles, title: 'À propos', body: [
      ['Ce qu’est BetterCommunity', 'BetterCommunity est la maison commune de l’écosystème Better* — un hub où la communauté découvre, partage et héberge du contenu pour des outils comme Better Mods Manager (BMM), Better Sound Maker (BSM) et BetterInstaller. Un seul compte, un seul endroit : parcours les catalogues, publie vos mods, plugins, thèmes et presets, et lance un Server-Repo hébergé.'],
      ['Notre mission', 'Offrir aux créateurs une plateforme claire et honnête : pas de pub, pas de dark patterns, jamais de revente de vos données. Les fichiers sont recontrôlés à chaque changement, et l’ensemble est conçu pour rester rapide et léger.'],
      ['Comment les choses sont publiées', 'Il y a deux voies ici et elles ne se valent pas, alors nous disons laquelle vous regardez plutôt que de laisser croire qu’elles sont identiques. Le catalogue OFFICIEL est vérifié avant d’apparaître : un envoi reste invisible tant qu’une personne de l’équipe ne l’a pas ouvert et approuvé, et un refus est motivé. Les catalogues COMMUNAUTAIRES et les Server-Repos hébergés partent en ligne quand leur propriétaire le décide — sans file et sans attente. Chacun affiche le compte qui l’a mis en ligne, n’importe qui peut signaler un problème, et nous suspendons ce qui enfreint les règles. Vérifié après publication, donc, et signalé comme tel partout où il apparaît.'],
      ['Les projets', 'BMM gère les mods des jeux pris en charge avec un vrai système de plugins/thèmes. BSM est un catalogue de presets sonores. BetterInstaller est un installeur moderne et rapide pour la suite. Les Server-Repos permettent aux créateurs d’héberger leurs propres dépôts chez nous, facturés uniquement selon l’usage. Chaque catalogue est rempli par la communauté, et les contributeurs sont crédités sur chaque page de projet.'],
      ['Construire dessus', 'La plateforme est ouverte aux autres logiciels : une API REST, OpenID Connect pour que les gens se connectent à votre projet avec leur compte d’ici, et des webhooks pour être prévenu quand leur contenu change. Aucun SDK, et une clé prend une minute. Si la chose que vous voulez n’existe pas et que vous préfèrez ne pas la construire, une commande commence par une consultation payante — conseil et devis — et le travail ne démarre qu’une fois ce devis approuvé.'],
      ['Ouvert & transparent', 'Nos règles de modération, nos tarifs et nos pratiques de confidentialité sont tous documentés dans ces pages légales — aucune surprise. Chaque politique conserve ses versions publiées : vous pouvez relire exactement le texte que vous avez accepté, et non celui d’aujourd’hui. Et savoir si le site est en ligne est une page publique avec ses propres sondes, pas une affirmation. Un problème ou une idée ? La page Contact et notre Discord sont les moyens les plus rapides de nous joindre.'],
      ['Soutenir le projet', 'BetterCommunity est financé par la communauté. Les coûts d’hébergement sont couverts par les offres Server-Repo payantes et par les dons sur Ko-fi. Chaque don sert directement à faire tourner les serveurs — merci.'],
    ] },
    refunds: { icon: Receipt, title: 'Paiements & Remboursements', body: [
      ['Fonctionnement de la facturation', 'Trois choses sont payantes : (1) les Server-Repos et pools de stockage hébergés, facturés selon la capacité, la bande passante et les options choisies ; (2) le stockage de fichiers de catalogue chez nous au-delà du seuil gratuit, ainsi que les mises en avant « featured » optionnelles ; et (3) les produits vendus sur la marketplace d’un projet — soit une fois, soit sous forme d’abonnement qui se renouvelle jusqu’à votre annulation. Tout est traité par Stripe — nous ne voyons ni ne stockons jamais votre carte. Sur une vente de la marketplace, nous prenons une commission, indiquée au vendeur avant sa mise en vente ; le reste revient au vendeur. S’y ajoute (4) une place d’équipe supplémentaire au-delà du nombre d’équipes qu’un compte peut posséder gratuitement — un paiement unique qui reste attaché au compte. Et (5) les plans du bot Discord, un abonnement mensuel qui débloque des fonctions et des limites plus hautes du bot sur les serveurs que vous choisissez, vendu seul ou inclus dans un plan de stockage.'],
      ['Prix & devise', 'Les prix sont affichés avant confirmation, dans la devise prise en charge par votre moyen de paiement. Les offres récurrentes se renouvellent automatiquement jusqu’à résiliation. Nous pouvons modifier les prix avec préavis ; un changement n’affecte jamais une période déjà payée.'],
      ['Si un prix augmente', "Nous prévenons par e-mail chaque abonné concerné avant qu'une hausse ne prenne effet, à l'adresse du compte, et le même avis apparaît dans votre compte — un e-mail peut passer inaperçu, et le mois où il passe inaperçu est justement celui du préavis. L'avis indique le prix actuel, le nouveau, et la date exacte du changement. Le nouveau prix s'applique à partir de votre PROCHAIN renouvellement, jamais à une période déjà payée, et jamais en cours de terme sur une formule prépayée. Vous pouvez résilier avant ce renouvellement et conserver le service jusqu'à la fin de la période payée — résilier suffit toujours à refuser une hausse. Certaines formules sont tarifées à partir de nos taux publiés par Go et par Mbps plutôt qu'à un montant fixe : leur prix suit donc ces taux, avec le même préavis et la même règle du prochain renouvellement."],
      ['Offre gratuite', 'Chaque compte reçoit un seuil de stockage gratuit pour l’hébergement et un seuil gratuit d’upload de catalogue — vous ne payez que ce qui dépasse. L’offre gratuite est réellement gratuite : aucune carte requise, aucun essai qui se transforme silencieusement en abonnement.'],
      ['Résiliation', 'Vous pouvez résilier un abonnement d’hébergement à tout moment depuis votre tableau de bord. La résiliation stoppe le prochain renouvellement ; votre dépôt reste en ligne jusqu’à la fin de la période déjà payée, puis est mis hors ligne.'],
      // N-hosting (agent-hosting-N) : termes prépayés, arrêt du service, et remise fidélité.
      ['Termes prépayés', 'Payer d’avance achète exactement le terme choisi (1, 6 ou 12 mois), et rien au-delà. Les termes longs coûtent moins cher par mois, et c’est la seule chose que la durée change. Nous ne vendons pas de termes de plus de 12 mois, parce que nous ne promettons pas le service des années à l’avance. Si nous arrêtons le service, ou la formule que vous avez prépayée, avant la fin de votre terme, nous remboursons la partie non utilisée du terme, au prorata au jour près, sans que vous ayez à le demander, et votre contenu reste téléchargeable jusqu’à l’arrêt du service. Votre propre droit à un remboursement au prorata de la partie non utilisée (voir « Politique de remboursement ») s’applique à un terme prépayé comme à tout autre.'],
      ['Remise fidélité', 'Quand nous la proposons, un abonnement d’hébergement qui se renouvelle sans interruption reçoit une remise sur ses renouvellements dès qu’il atteint les paliers affichés sur la page Hébergement (par exemple 5 % après 3 mois), jusqu’au maximum qui y est indiqué. Le compte démarre le jour du premier paiement. Il repart de zéro si l’abonnement est résilié (par vous, ou arrêté après l’échec des nouvelles tentatives de paiement), ou si un renouvellement est payé plus tard que le délai de grâce après la fin du terme payé (72 heures par défaut pour un terme renouvelé à la main, une semaine après un paiement par carte refusé). Un nouveau pool est un nouvel abonnement et part de zéro. La remise s’applique à partir du renouvellement qui suit un palier, jamais à un terme déjà payé, et elle n’est ni remboursée ni créditée quand un abonnement prend fin. Réduire ou supprimer les paliers fidélité compte comme une hausse de prix pour les renouvellements concernés, et suit « Si un prix augmente ».'],
      ['Si votre compte est suspendu ou banni', 'Une sanction arrête le service, donc elle arrête aussi l’argent : tout abonnement actif est résilié au moment où une suspension ou un bannissement est appliqué, et vous n’êtes plus prélevé. Ce qui diffère entre les deux, c’est l’accès — une SUSPENSION vous laisse vous connecter, pour lire le motif, contester et récupérer vos factures ; un BANNISSEMENT non. Dans les deux cas, vos dépôts, catalogues et éléments sont SUSPENDUS et non supprimés : rien n’est détruit, et si la sanction est levée, chacun retrouve l’état où il était — un dépôt qui était hors ligne revient hors ligne. Les abonnements sont l’exception : ils sont résiliés chez le prestataire de paiement et ne sont pas rétablis, vous devriez en reprendre un. La période déjà payée n’est pas remboursée automatiquement quand la sanction est motivée ; si vous pensez qu’il y a erreur, contactez-nous et une personne regardera.'],
      ['Politique de remboursement', 'Si vous demandez un remboursement pendant un abonnement déjà payé, nous vous rendons la partie que vous n’avez pas encore utilisée : le temps déjà écoulé sur la période en cours est déduit, et la portion restante, inutilisée, vous est remboursée, au prorata (au jour près). Annuler, à l’inverse, arrête simplement le renouvellement suivant et conserve votre service jusqu’à la fin de la période payée. Lorsque la faute est de notre fait — une erreur de facturation, un débit que vous n’avez pas effectué, ou une panne prolongée de notre fait — nous remboursons INTÉGRALEMENT la période concernée, sans déduire le temps consommé. Écrivez-nous via la page Contact avec l’e-mail du compte et la date et le montant approximatifs ; les remboursements approuvés sont renvoyés vers le moyen de paiement d’origine via Stripe sous quelques jours ouvrés. La seule exception au prorata est un abonnement résilié pour faute — une suspension ou un bannissement pour violation des présentes conditions — voir « Si votre compte est suspendu ou banni ».'],
      ['Achats sur la marketplace', 'Un produit de la marketplace se vend soit UNE FOIS, soit sous forme d’abonnement. Un abonnement suit les mêmes règles que tout le reste de cette page : résilier arrête le renouvellement suivant, ou demandez un remboursement et la partie non utilisée vous est rendue au prorata, au jour près.\n\nUn produit vendu une fois est un CONTENU NUMÉRIQUE délivré dès que votre paiement aboutit — une clé, un fichier, une licence, un texte révélé, ou un rôle Discord. Il n’y a rien à mettre au prorata et rien à rendre : une fois qu’une clé est à l’écran, vous l’avez. La règle est donc différente, et la voici. Si le produit est défectueux, ne correspond pas à la description de sa page, ou n’a jamais été délivré, nous le remboursons intégralement — dites-le-nous et nous ne discuterons pas. Si vous avez simplement changé d’avis après la livraison, le remboursement relève de notre appréciation, parce que nous ne pouvons pas annuler la livraison. Le droit du consommateur ci-dessous n’est affecté par rien de tout cela.\n\nÀ QUI VOUS AVEZ ACHETÉ. Certains produits sont les nôtres, d’autres appartiennent à un autre projet du site. Dans les deux cas, votre contrat pour le PAIEMENT est avec nous : nous encaissons, nous émettons la facture, et c’est nous que vous contactez. Nous gardons une commission et le reste est transféré au vendeur. Quand nous vous remboursons, nous récupérons ce transfert auprès du vendeur — cela se règle entre lui et nous, jamais quelque chose que vous ayez à poursuivre.'],
      ['Plans du bot Discord', 'Un plan du bot Discord est un abonnement facturé chaque mois jusqu’à ce que vous l’annuliez depuis Facturation, et il suit les mêmes règles que tous les autres abonnements de cette page : résilier arrête le renouvellement suivant, un remboursement rend la partie non utilisée au prorata du jour, et une faute de notre part est remboursée intégralement. Quand il se termine, rien n’est supprimé sur votre serveur : ses réglages sont conservés et ce que le plan ajoutait cesse de s’appliquer. Un plan inclus dans un plan de stockage commence, se renouvelle et se termine avec ce plan de stockage et n’est pas facturé à part.'],
      ['Échec de paiement & suppression des données', 'Si un renouvellement échoue, vous disposez d’au moins 72 heures (actuellement sept jours) pour mettre à jour votre moyen de paiement et renouveler. Passé ce délai, les données stockées pour cet abonnement (fichiers de Server-Repo hébergés et contenu associé) sont supprimées sans préavis ni sauvegarde — gardez donc votre propre copie.'],
      ['Consultations & commandes (Make Your Own)', 'Les frais de consultation paient un conseil et un devis — un service que nous fournissons dès que nous vous répondons. Une fois ce conseil fourni, ils ne sont pas remboursables ; si nous ne pouvons pas vous aider du tout et ne donnons aucun conseil, nous les remboursons. Le paiement d’un devis commande un travail sur mesure réalisé selon vos instructions : une fois ce travail commencé, il n’est pas remboursable pour la part déjà effectuée. Si nous ne livrons pas ce que décrit le devis et ne pouvons pas y remédier, nous remboursons la part non livrée. Valider un devis vaut demande de commencer immédiatement, ce qui réduit ou supprime tout droit de rétractation légal pour le travail déjà réalisé, comme le permet le droit de la consommation. Un devis qui expire, que vous refusez ou que nous retirons n’est pas un prélèvement, donc pas un remboursement — rien n’a été pris. Les frais de consultation sont distincts de tout devis et ne s’en déduisent pas, sauf si le devis le précise. Les fichiers livrés sont remis par un lien de téléchargement daté : il fonctionne TRENTE JOURS après la livraison, ou SEPT JOURS après votre premier téléchargement, au premier des deux, et votre premier téléchargement est consigné dans la conversation de la demande — cette mention est notre preuve de livraison et le point de départ des sept jours. Passée la date, le fichier est supprimé de nos serveurs et ne peut pas être réémis : téléchargez et conservez votre copie à temps ; une fois la demande archivée, la conversation est conservée sans ses pièces jointes.'],
      ['Votre droit de changer d’avis sous 14 jours (consommateurs UE/EEE)', 'Si vous êtes CONSOMMATEUR dans l’UE ou l’EEE — achat pour vous, pas pour une entreprise — vous disposez de QUATORZE JOURS à compter de l’achat d’un abonnement d’hébergement ou de référencement pour vous rétracter, sans avoir à vous justifier. Dites-le nous via la page Contact dans ces quatorze jours et nous vous remboursons.\n\nUne exception s’applique, fréquemment ignorée. Quand vous nous demandez de commencer immédiatement — ce qu’un achat d’hébergement signifie normalement, puisque le service devient disponible aussitôt — il vous est demandé de reconnaître que démarrer tôt réduit ce droit : vous pouvez toujours vous rétracter dans les quatorze jours, mais nous pouvons conserver un montant proportionnel à ce qui a déjà été fourni. Si vous demandez un démarrage immédiat ET que le service est intégralement exécuté dans le délai, le droit s’éteint. La simple mise à disposition ne vaut pas exécution intégrale.\n\nUNE RÈGLE DIFFÉRENTE S’APPLIQUE AU CONTENU NUMÉRIQUE, et un produit de la marketplace acheté une fois en est un. Lorsqu’un tel contenu est fourni immédiatement, le droit de rétractation prend fin dès que la fourniture a commencé — mais uniquement si vous avez expressément demandé qu’elle commence et reconnu que vous perdiez ce droit. Un paiement sur la marketplace vous demande exactement cela, et c’est affiché avant de payer, pas enfoui après. Si on ne vous l’a pas demandé, le droit n’est pas perdu et nous vous remboursons. Cela ne touche pas un produit défectueux ou mal décrit, qui est remboursé dans tous les cas.\n\nCe droit est distinct de tout le reste de cette page, et s’y ajoute. Rien ici ne le supprime, et une clause qui essaierait de le faire serait inopposable à un consommateur.'],
      ['Comment demander un remboursement', 'Contactez-nous via la page Contact avec l’e-mail de votre compte et la date/le montant approximatif du débit. Nous répondons sous quelques jours ouvrés. Les remboursements approuvés sont renvoyés sur le moyen de paiement d’origine via Stripe.'],
      ['Oppositions bancaires (chargebacks)', 'Si quelque chose semble anormal, contacte-nous d’abord — nous résolvons presque toujours plus vite qu’un litige bancaire. Ouvrir un chargeback sans nous contacter peut entraîner la suspension du compte et des dépôts associés en attendant résolution.\n\nSur une vente de la marketplace, le chargeback est à nous d’y répondre, puisque c’est nous qui avons encaissé. Si le produit appartenait à un autre vendeur et que nous perdons le litige, nous récupérons le montant sur sa part.'],
    ] },
    submissions: { icon: FileText, title: 'Conditions de soumission', body: [
      ['Ce que ça couvre', 'Ces conditions s’appliquent quand vous nous demandez de référencer ou d’héberger quelque chose : un Server-Repo, des fichiers de catalogue, ou une fiche « Autres projets ». Soumettre est une demande d’EXAMEN — cela ne nous oblige à rien publier, héberger ni conserver, et une page ou un fichier ne paraît qu’après examen par une personne ici.'],
      ['Open-source et closed-source', 'Nous référençons les deux. Un projet OPEN-SOURCE peut être soumis par n’importe qui — son auteur, ou quelqu’un qui l’apprécie simplement — et doit indiquer sa licence. Un projet CLOSED-SOURCE ne peut être soumis QUE par l’ayant droit, et uniquement avec une preuve de droits jointe : sans preuve, nous ne l’ajoutons pas.'],
      ['La preuve de droits, et comment nous la traitons', 'La preuve que vous téléversez pour une fiche closed-source (une licence, une facture, une déclaration signée) est stockée de façon PRIVÉE — jamais servie publiquement, visible uniquement par le personnel d’examen et par vous, et SUPPRIMÉE dès qu’une décision est prise (acceptation, refus ou retrait). Ne téléversez que le minimum nécessaire pour établir les droits ; ne téléversez pas les données personnelles d’autrui sans base légale.'],
      ['Vos déclarations', 'En soumettant, vous déclarez que les informations sont exactes, que vous avez le droit de demander ce référencement, et — pour un projet qui est le vôtre — que vous pouvez accorder l’autorisation nécessaire à son affichage. Une fausse déclaration justifie le retrait de la fiche et, en cas d’abus répété, une sanction du compte.'],
      ['Les examens payants ne sont pas remboursables', 'Des frais d’examen payants achètent une PLACE DANS LA FILE et une priorité. Ils n’achètent pas un référencement, ne changent pas la réponse, et NE SONT PAS REMBOURSABLES — y compris si la demande est finalement refusée. Tout délai affiché est une ESTIMATION selon le nombre de demandes en attente : ce n’est pas une promesse, et payer ne garantit pas un délai. (Là où le droit de la consommation accorde un droit de rétractation, ce droit s’applique — voir Paiements & Remboursements.)'],
      ['Le fil de contact', 'Chaque soumission ouvre un fil privé dans votre tableau de bord, dans « Signalements & contact », où le personnel peut demander plus de détails et où vous pouvez répondre. Il n’est lisible que par vous et par le personnel.'],
      ['Retrait et vos droits (RGPD)', 'Vous pouvez retirer une demande en attente à tout moment, ce qui la supprime ainsi que toute preuve. Une acceptation ou un refus supprime aussi la preuve. Votre déclaration (auteur/fan, licence) est conservée avec le dossier pour justifier l’existence d’une fiche. Exercez vos droits RGPD (accès, rectification, suppression) via la page Contact ; la conservation est détaillée dans la Politique de confidentialité.'],
    ] },
    dpa: { icon: FileSignature, title: 'Accord de traitement des données', body: [
      ['Ce que c’est, et quand ça s’applique', 'La plupart du temps, c’est BetterCommunity qui décide pourquoi et comment vos données sont utilisées — pour votre compte, vos achats, les pages que vous lisez — et la Politique de confidentialité est le document qui le décrit. Cet accord couvre l’AUTRE situation : celle où c’est VOUS qui décidez et où nous ne faisons qu’exécuter. C’est le cas quand vous hébergez un Server-Repo ou un catalogue dont les fichiers ou les journaux d’accès concernent d’autres personnes, quand vous vendez sur une marketplace et que nous conservons pour vous les commandes de vos acheteurs, quand vous animez une équipe, et quand vous ajoutez notre bot Discord à un serveur que vous administrez — il conserve alors, pour vous, des compteurs d’activité, des décisions de modération et, si vous activez la journalisation, un journal de ce qui se passe sur ce serveur. Dans ces cas, vous êtes le RESPONSABLE DU TRAITEMENT au sens de l’article 4(7) du RGPD, nous sommes votre SOUS-TRAITANT au sens de l’article 4(8), et cet accord est le contrat de l’article 28(3) entre nous. Il fait partie des Conditions d’utilisation, s’applique dès que vous utilisez l’une de ces fonctions, et prévaut sur les Conditions là où elles diffèrent au sujet des données personnelles.'],
      ['Objet, durée, nature et finalité', 'OBJET : les données personnelles contenues dans, ou générées par, les contenus et services que vous nous confiez — fichiers de dépôts et de catalogues et leurs journaux de téléchargement, commandes de marketplace et coordonnées des acheteurs, composition des équipes, et activité de serveurs Discord, fiches de membres, actions de modération et journaux collectés par le bot à votre demande.\n\nDURÉE : tant que vous utilisez la fonction concernée, plus les durées de conservation indiquées dans la section « Conservation » de la Politique de confidentialité, qui sont celles que le service applique réellement.\n\nNATURE : stockage, mise à disposition des personnes que vous autorisez, comptage et — pour le bot — collecte d’événements depuis Discord, application des règles de modération que vous avez configurées, et écriture des entrées de journal que vous avez demandées. Nous ne lisons, ne profilons ni n’analysons ces données pour nos propres besoins.\n\nFINALITÉ : fournir les fonctions d’hébergement, de marketplace, d’équipe et de bot communautaire que vous avez choisies, et rien d’autre.'],
      ['Les données et les personnes concernées', 'CATÉGORIES DE DONNÉES : ce que contient votre contenu (nous ne l’inspectons pas), plus ce que la fonction produit elle-même — adresses IP dans les journaux d’accès des dépôts et des catalogues, avec la clé d’accès présentée et, si la personne est connectée ou son application liée, son identifiant de compte et son identifiant Discord ; noms, adresses e-mail et détails de commande des acheteurs ; identifiants Discord, pseudonymes, avatars, nombre de messages, temps en vocal, réactions, dates d’arrivée et de départ, rôles, avertissements, exclusions temporaires, expulsions et bannissements, et — uniquement si vous l’activez — le contenu et les modifications de messages qu’une catégorie de journal enregistre.\n\nPERSONNES CONCERNÉES : celles qui téléchargent depuis vos dépôts, vos acheteurs, les membres de vos équipes, et les membres des serveurs Discord que vous administrez.\n\nCATÉGORIES PARTICULIÈRES : aucune de ces fonctions n’est conçue pour des données révélant la santé, les convictions, l’orientation sexuelle, l’origine ethnique ou similaires. Si votre contenu ou votre serveur en contient, vous devez disposer d’une base légale au titre de l’article 9 et nous en informer avant de nous les confier ; nous pouvons refuser.'],
      ['Vos obligations de responsable du traitement', 'Vous garantissez disposer d’une base légale pour chaque traitement que vous nous instruisez, que les personnes concernées ont été informées comme l’exigent les articles 13 et 14 (une notice de confidentialité pour vos acheteurs, une mention sur votre serveur Discord indiquant que le bot journalise l’activité et ce qu’il journalise), que vous n’instruirez rien d’illicite, et que vous utiliserez les réglages des fonctions — catégories de journal, conservation, exemptions, qui voit quoi — comme le moyen d’exercer vos décisions. Les réglages de journalisation et d’automodération du bot SONT vos instructions : une catégorie que vous activez est une donnée que vous avez décidé de collecter, une catégorie laissée inactive est une donnée que nous ne collecterons pas.'],
      ['Nos obligations de sous-traitant', 'Nous traitons ces données UNIQUEMENT sur vos instructions documentées, à savoir : les Conditions, cet accord, les réglages que vous choisissez dans le produit, et toute instruction écrite supplémentaire transmise via la page Contact. Si nous estimons qu’une instruction enfreint la loi, nous vous le disons avant d’agir. Concrètement, nous :\n\n· ne donnons accès à vos données qu’au personnel tenu à la confidentialité et qui en a besoin pour faire fonctionner le service ou vous répondre ;\n· appliquons les mesures de sécurité décrites dans la section « Sécurité » de la Politique de confidentialité (hachage argon2id des mots de passe, HTTPS partout, base de données non exposée à Internet, double authentification obligatoire pour le personnel, journal d’audit chaîné par empreintes des actions privilégiées, limites de débit et blocage automatique, sauvegardes quotidiennes) — ce sont les mesures de l’article 32, et ce sont celles que le service applique réellement, pas une liste générique ;\n· vous aidons à répondre aux demandes des personnes concernées (accès, rectification, effacement, limitation, portabilité, opposition) portant sur les données que nous détenons pour vous — la plupart se traitent avec les outils du produit (supprimer un fichier, une entrée de journal, la fiche d’un membre, fermer le tableau de bord du serveur), et pour le reste nous agissons dans un délai raisonnable sur votre demande écrite ;\n· vous assistons pour les articles 32 à 36 — sécurité, notification des violations, analyses d’impact et consultation préalable — dans la mesure où l’information nous appartient ;\n· supprimons ou restituons les données à la fin du service comme décrit plus bas ;\n· mettons à disposition les informations nécessaires pour démontrer notre conformité et permettons les audits décrits plus bas.'],
      ['Sous-traitants ultérieurs', 'Vous autorisez les sous-traitants listés sous « Sous-traitants » dans la Politique de confidentialité, chacun pour la seule finalité qui y est indiquée. Notre hébergeur et fournisseur de stockage objet détient les serveurs et les fichiers ; Stripe détient les données de paiement de vos acheteurs ; Discord est la plateforme sur laquelle le bot opère. Nous vous informons de tout ajout ou remplacement envisagé d’un sous-traitant au moins TRENTE JOURS avant sa prise d’effet, par e-mail à l’adresse de votre compte et par une note sur la page de la Politique de confidentialité, et vous pouvez vous y opposer dans ce délai ; si nous ne parvenons pas à résoudre l’objection, vous pouvez mettre fin à la fonction concernée et nous remboursons ce que vous aviez prépayé pour elle. Chaque sous-traitant est lié par un contrat écrit imposant les mêmes obligations que cet accord, et nous restons pleinement responsables envers vous de leur exécution.'],
      ['Où sont les données, et transferts hors EEE', 'Le service est exploité pour des utilisateurs de l’Union européenne et de l’Espace économique européen, et nous préférons des sous-traitants qui traitent sur ce territoire. Lorsqu’un sous-traitant traite des données personnelles hors EEE — Stripe, Google, GitHub et Discord sont des groupes comptant des entités aux États-Unis — le transfert repose sur une décision d’adéquation de la Commission européenne lorsqu’elle existe, sinon sur les clauses contractuelles types adoptées par la Commission, avec les mesures supplémentaires documentées par le sous-traitant. Nous ne transférons pas nous-mêmes vos données hors EEE, sauf par ces sous-traitants et pour ces finalités.'],
      ['En cas de violation de données', 'Si nous prenons connaissance d’une violation de données personnelles touchant des données que nous traitons pour vous, nous vous en informons SANS DÉLAI INDU et en tout état de cause dans les 48 heures suivant cette prise de connaissance — par e-mail à l’adresse de votre compte — avec ce que nous savons alors : la nature de la violation, les catégories et le nombre approximatif d’enregistrements et de personnes concernés, les conséquences probables, et les mesures prises ou proposées. Nous complétons cette notification au fur et à mesure. Le délai de 72 heures de l’article 33 pour notifier l’autorité de contrôle court pour vous en tant que responsable ; notre notification est calée pour que vous puissiez le tenir.'],
      ['Audits', 'Sur demande écrite, au plus une fois par période de douze mois sauf motif donné par une autorité de contrôle ou une violation, nous fournissons la documentation montrant comment nous respectons cet accord — la section Sécurité, notre liste de sous-traitants, les résultats des revues de sécurité effectuées, et des réponses à un questionnaire écrit raisonnable. Si cela ne suffit pas, vous ou un auditeur indépendant tenu à la confidentialité pouvez auditer les parties pertinentes du service, à vos frais, avec un préavis de trente jours, à un moment qui ne perturbe pas les autres clients, et sans accès aux données des autres clients.'],
      ['Fin du service : suppression ou restitution', 'Quand vous cessez d’utiliser une fonction — vous supprimez un dépôt ou un catalogue, fermez une équipe, retirez le bot de votre serveur, ou fermez votre compte — les données que nous détenons pour elle sont supprimées dans les délais de conservation que la Politique de confidentialité indique pour ces données (l’activité et les journaux d’un serveur retiré sont supprimés au balayage suivant, les sauvegardes expirent dans la durée de rétention des sauvegardes). Avant cela, vous pouvez exporter ce que nous détenons : les fichiers de dépôts et les catalogues se téléchargent en archives, les commandes de marketplace s’exportent depuis votre tableau de bord vendeur, et la base de membres et les journaux du bot s’exportent depuis le tableau de bord du serveur. Nous ne conservons aucune copie une fois la durée de conservation écoulée, sauf obligation légale.'],
      ['Responsabilité et le reste', 'Chaque partie répond du dommage qu’elle cause par un traitement contraire au RGPD, comme le prévoit l’article 82, et les limitations de responsabilité des Conditions d’utilisation s’appliquent à cet accord sauf là où le RGPD ne le permet pas. Si une partie de cet accord est jugée invalide, le reste demeure et la partie invalide est interprétée au plus près de son intention dans les limites de la loi. Cet accord est régi par le droit qui régit les Conditions, et les tribunaux qui y sont désignés sont compétents. Nous pouvons mettre à jour cet accord comme les Conditions sont mises à jour ; un changement qui réduit votre protection est annoncé trente jours à l’avance et vous pouvez mettre fin à la fonction concernée avant qu’il ne s’applique.'],
      ['Contact', 'Les questions sur cet accord, les instructions à consigner, les objections à un sous-traitant et les demandes d’audit passent toutes par la page Contact, qui est le point de contact électronique unique nommé dans les Conditions. Pour l’identité du responsable du traitement lorsque c’est NOUS qui le sommes — votre compte, vos achats, ce site — voyez la Politique de confidentialité.'],
    ] },
  },
};

