// When these texts last actually changed. A real date, edited with the text — the header
// used `new Date()`, so every one of these pages claimed to have been updated today, every
// day, whatever it said. On a policy page that is the one line a reader uses to decide
// whether the terms they agreed to are still the terms in front of them.
const LEGAL_UPDATED = '2026-09-24';

// ── Rendering a policy ───────────────────────────────────────────────────────
//
// The text is authored as plain strings on purpose — there is no markdown parser in the
// path, so nothing here can misread a policy and render it as something it does not say.
// What follows is the smallest amount of structure that makes it READ like a legal
// document instead of a wall: a run of `· ` lines is a list, a run of `1. ` or `a. ` lines
// is an ordered list, and everything else stays a paragraph. Any line that does not match
// falls through unchanged rather than being dropped.

// Two or more consecutive ALL-CAPS words become emphasis. Authored that way throughout —
// "ALL THREE", "HAS BEEN NOTIFIED", "FOURTEEN DAYS" — and left as literal capitals it reads
// as shouting. Each token must be at least two capitals, so a lone acronym followed by a
// capitalised word ("DSA Article 16") is NOT swept up: `Article` contributes only `A`, which
// is one character and fails the rule.
const CAPS_RUN = /(\p{Lu}[\p{Lu}\d’'-]+(?:\s+\p{Lu}[\p{Lu}\d’'-]+)+)/gu;

function Emphasised({ text }) {
  const parts = String(text).split(CAPS_RUN);
  return parts.map((s, i) => (
    // The odd indices are the captured runs. Emphasis is a colour change and a weight, not
    // a different size: a legal page where phrases jump around in scale reads as a flyer.
    i % 2 ? <strong key={i} className="font-semibold text-[var(--text)]">{s}</strong> : <span key={i}>{s}</span>
  ));
}

const BULLET = /^·\s+/;
const NUM = /^(\d{1,2})\.\s+/;
const ALPHA = /^([a-z])\.\s+/;

function LegalParagraph({ text }) {
  const lines = String(text).split('\n');
  const blocks = [];
  for (const line of lines) {
    const kind = BULLET.test(line) ? 'ul' : NUM.test(line) ? 'ol' : ALPHA.test(line) ? 'oa' : 'p';
    const content = line.replace(BULLET, '').replace(NUM, '').replace(ALPHA, '');
    const last = blocks[blocks.length - 1];
    // A paragraph never merges with the one before it — only list items group, because two
    // adjacent prose lines inside one entry are a deliberate line break, not one sentence.
    if (last && last.kind === kind && kind !== 'p') last.items.push(content);
    else blocks.push({ kind, items: [content] });
  }
  return blocks.map((b, i) => {
    if (b.kind === 'p') {
      return b.items.map((s, k) => (
        <p key={`${i}-${k}`} className="text-[var(--muted)] leading-relaxed mb-3 last:mb-0">
          {s ? <Emphasised text={s} /> : <br />}
        </p>
      ));
    }
    const Tag = b.kind === 'ul' ? 'ul' : 'ol';
    return (
      <Tag key={i}
        className={`mb-3 last:mb-0 space-y-1.5 text-[var(--muted)] leading-relaxed ${
          b.kind === 'ul' ? 'list-disc' : b.kind === 'oa' ? 'list-[lower-alpha]' : 'list-decimal'
        } ps-5 marker:text-[var(--accent-ink)]`}>
        {b.items.map((s, k) => <li key={k}><Emphasised text={s} /></li>)}
      </Tag>
    );
  });
}

/**
 * The five documents that ship with the app, in the order they have always been listed.
 *
 * Used only when the API is unreachable. It is not the list of what exists — that comes from
 * the server, because the whole point is that an admin can add to it — it is the list of what
 * has a compiled-in fallback text, which is why it is also the list that keeps working when
 * nothing loads.
 */
const BUILTIN_ORDER = ['about', 'privacy', 'terms', 'cookies', 'refunds', 'submissions', 'dpa'];
// Documents that ship in the bundle but are OFF until published (the API says the same list;
// this copy is only what the fallback uses when the API cannot be reached). A deployment that
// does not offer the addendum should not show one, and the bundled text must not leak past
// the switch just because the browser happens to carry it.
const OPTIONAL_KEYS = ['dpa'];
/** `{{dpa}}` in a policy becomes the pointer sentence when the addendum is on, nothing when it is off. */
const fillPointers = (text, lang, dpaOn) => String(text ?? '').replace(/\{\{dpa\}\}/g, dpaOn ? (DPA_POINTER[lang] || DPA_POINTER.en) : '');
const isOn = (key, menu) => !OPTIONAL_KEYS.includes(key) || !!menu?.pages?.some((x) => x.key === key);
// The sentence in the privacy policy that points at the addendum. Kept out of the policy's
// own text because it is only true when the addendum is on: a cross-reference to a page that
// does not exist is the kind of error nobody re-reads a policy to find.
const DPA_POINTER = {
  en: '\n\nWhen the roles are reversed — you are the controller and we process for you, as for a hosted repository, a marketplace’s buyers, a team or the Discord bot’s logs — the Data Processing Addendum (under Legal) is the contract that applies, and this list is the sub-processor list it refers to.',
  fr: '\n\nQuand les rôles s’inversent — vous êtes responsable du traitement et nous traitons pour vous, comme pour un dépôt hébergé, les acheteurs d’une marketplace, une équipe ou les journaux du bot Discord — l’Accord de traitement des données (rubrique Légal) est le contrat qui s’applique, et cette liste est la liste de sous-traitants à laquelle il renvoie.',
};

/** The icon a built-in document has always had. */
const BUILTIN_ICON = { about: Sparkles, privacy: Lock, terms: ShieldCheck, cookies: Cookie, refunds: Receipt, submissions: FileText, dpa: FileSignature };

/**
 * A built-in's label, from the dictionary rather than from the database.
 *
 * These five are translated by the app, and they were long before there was a table to store
 * a French label in. Reading the stored one instead would show an English "Privacy Policy" to
 * a French reader on a site that has always said "Politique de confidentialité" — a
 * regression produced by adding a feature nobody used yet.
 */
function builtinLabel(key, t) {
  switch (key) {
    case 'about': return t('foot.about', 'About');
    case 'privacy': return t('foot.privacy');
    case 'terms': return t('foot.terms');
    case 'cookies': return t('foot.cookies');
    case 'refunds': return t('foot.refunds', 'Payments');
    case 'submissions': return t('foot.submissions', 'Submission Terms');
    case 'dpa': return t('foot.dpa', 'Data Processing Addendum');
    default: return '';
  }
}

/** The glyph for a document: its built-in one, the name an admin chose, or the generic. */
function docIcon(key, icon, size = 18) {
  const I = BUILTIN_ICON[key];
  if (I) return <I size={size} />;
  if (icon) return <IconGlyph name={icon} size={size} />;
  return <FileText size={size} />;
}

export function Legal({ page: fixed }) {
  const { lang, t } = useI18n();
  // `/legal/:key` for anything an admin created; the five original routes still pass their
  // key as a prop, so every old link keeps working without a redirect.
  const params = useParams();
  const page = fixed || params.key || '';
  const builtIn = (LEGAL[lang] || LEGAL.en)[page];
  const summary = (LEGAL_SUMMARY[lang] || LEGAL_SUMMARY.en)[page];

  // Database first, built-in defaults otherwise — per DOCUMENT, never mixed. A page
  // assembled half from the database and half from the code is one nobody can diff, and the
  // failure would be invisible: it would just quietly say two different things.
  //
  // `null` means "not asked yet" and is deliberately distinct from `{}` ("asked, nothing
  // there"). Rendering the built-in text during the fetch and then swapping it would show a
  // reader one policy and then another, which on this page is worse than a blank moment.
  const [remote, setRemote] = useState(null);
  const [menu, setMenu] = useState(null);
  useEffect(() => {
    let alive = true;
    api.get('/legal').then((r) => {
      if (!alive) return;
      setRemote(r?.docs || {});
      setMenu({ pages: r?.pages || [], categories: r?.categories || [] });
    })
      // A failed fetch falls back to the built-in text rather than to an error: the policy
      // in the bundle is a correct policy, just possibly an older one.
      .catch(() => { if (alive) { setRemote({}); setMenu({ pages: [], categories: [] }); } });
    return () => { alive = false; };
  }, []);

  const override = remote?.[page];
  // The menu row for this document, when there is one. It carries the title and the icon for
  // a page an admin created — a built-in has both in the bundle, a new one has neither.
  const row = menu?.pages?.find((x) => x.key === page) || null;
  const rowTitle = row && ((lang === 'fr' && row.labelFr) || row.label);
  const rowIcon = row?.icon ? () => <IconGlyph name={row.icon} size={20} /> : null;
  // An optional document is only a document once it is published. Waiting for the menu
  // before deciding is what stops the addendum flashing on screen in the moment between the
  // first render and the fetch — on a policy page, showing a contract and then taking it
  // away is worse than a blank second.
  const optional = OPTIONAL_KEYS.includes(page);
  const on = isOn(page, menu);
  const dpaOn = isOn('dpa', menu);
  const d = override
    ? {
      icon: builtIn?.icon || rowIcon || FileText,
      title: builtIn?.title || rowTitle || page,
      body: override.sections.map((sec) => [
        (lang === 'fr' && sec.titleFr) || sec.title,
        fillPointers((lang === 'fr' && sec.bodyFr) || sec.body, lang, dpaOn),
      ]),
      markdown: true,
    }
    : (builtIn && { ...builtIn, body: builtIn.body.map(([h, b]) => [h, fillPointers(b, lang, dpaOn)]) });
  // An optional document nobody switched on: the text exists in the bundle and must not be
  // shown. Said plainly rather than 404'd — the address is in the app, and "this deployment
  // does not offer it" is the true answer.
  if (optional && !on) {
    if (menu === null) return <Loading />;
    return (
      <div className="max-w-3xl mx-auto py-16 text-center">
        <PageHeader icon={FileSignature} title={builtIn?.title || page}
          subtitle={t('legal.off.s', 'This document is not part of this site’s terms.')} />
        <Link to="/legal"><Button><ArrowLeft size={14} /> {t('legal.all', 'All')}</Button></Link>
      </div>
    );
  }
  // A key with neither stored sections nor a compiled-in fallback. It can be reached: an
  // admin creates a page and links to it before writing anything in it, and a 404 there would
  // read as "the site is broken" rather than "there is nothing here yet".
  if (!d) {
    return (
      <div className="max-w-3xl mx-auto py-16 text-center">
        <PageHeader icon={FileText} title={rowTitle || t('legal.empty.t', 'Nothing here yet')}
          subtitle={t('legal.empty.s', 'This document has been created but not written.')} />
        <Link to="/legal"><Button><ArrowLeft size={14} /> {t('legal.all', 'All')}</Button></Link>
      </div>
    );
  }
  // Once a document is database-backed its own newest edit is the honest date; the constant
  // would freeze at whatever the source file last said while the text kept changing.
  const updated = override?.updatedAt ? String(override.updatedAt).slice(0, 10) : LEGAL_UPDATED;
  // Which section you are actually reading. A 32-entry contents list with nothing marked is
  // a list you have to re-find your place in every time you glance at it.
  const [active, setActive] = useState(0);
  useEffect(() => {
    const secs = Array.from(document.querySelectorAll('section[id^="s"]'));
    if (!secs.length) return undefined;
    const io = new IntersectionObserver((entries) => {
      // The topmost section currently on screen wins. Taking "the last one that intersected"
      // makes the marker jump backwards when you scroll up past a short section.
      const vis = entries.filter((e) => e.isIntersecting)
        .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
      if (vis) setActive(Number(vis.target.id.slice(1)));
    }, { rootMargin: '-80px 0px -70% 0px' });
    secs.forEach((s) => io.observe(s));
    return () => io.disconnect();
  }, [page, lang]);
  // The strip of other documents. From the live list, so a page an admin created appears in
  // it — and so does a rename. The five built-in labels stay translated through the
  // dictionary rather than through the stored English, because they always have been.
  //
  // A LIST for a switcher, not a row of buttons: see ui/doc-switcher.jsx for what the row
  // did at each end of the width range. The "All" entry is the first option rather than a
  // button beside it, so there is exactly one control here and it can never wrap or overflow.
  const tabs = [
    { key: '__all', to: '/legal', label: lang === 'fr' ? 'Tous les documents' : 'All documents', icon: <FileText size={15} className="text-[var(--accent-ink)]" /> },
    ...(menu?.pages?.length ? menu.pages : BUILTIN_ORDER.filter((k) => !OPTIONAL_KEYS.includes(k)).map((k) => ({ key: k, builtIn: true })))
      .map((x) => ({
        key: x.key,
        to: `/legal/${x.key}`,
        label: builtinLabel(x.key, t) || (lang === 'fr' && x.labelFr) || x.label || x.key,
        icon: docIcon(x.key, x.icon || '', 15),
      })),
  ];
  return (
    <div className="max-w-5xl mx-auto" id="legal-print">
      <PageHeader icon={d.icon} title={d.title} subtitle={`${lang === 'fr' ? 'Mis à jour le' : 'Last updated'} ${new Date(`${updated}T00:00:00`).toLocaleDateString()}`} />
      {/* One control that names the document you are reading and opens the rest. */}
      <div className="mb-5 flex items-center gap-2 flex-wrap">
        <span className="plate px-1 text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)]">{lang === 'fr' ? 'Document' : 'Document'}</span>
        <DocSwitcher options={tabs} current={page} label={d.title} className="min-w-0 w-full sm:w-auto" />
      </div>
      {/* The plain-language summary.
          It used to be painted with a full-strength accent gradient fading to transparent,
          which put muted grey text on solid orange at one end and on the page at the other:
          the same sentence changed contrast across its own width, and the card read as an
          advert rather than as the human-readable version of the document. A quiet tint and
          an accent rule on the leading edge say "this is the summary" without competing
          with the text it summarises, and it survives the Translucent surfaces setting
          because `.tint-primary` is a painted rule rather than an alpha on a variable. */}
      <Card className="p-4 mb-6 flex items-start gap-3 tint-primary border-l-[3px] border-l-[var(--primary)] print:border print:bg-none">
        <d.icon size={18} className="text-[var(--accent-ink)] mt-0.5 shrink-0" />
        <div className="text-sm text-[var(--text)]">{summary}</div>
      </Card>
      {/* On a phone the contents were `hidden md:block` — which is to say, absent. A
          thirty-two-section policy with no way to jump is a document you scroll past, so the
          same list is a <details> above the text there. */}
      <details className="md:hidden mb-4 rounded-xl border border-[var(--line)] bg-[var(--surface)] print:hidden">
        <summary className="px-4 py-3 text-sm font-medium cursor-pointer select-none">{lang === 'fr' ? 'Sur cette page' : 'On this page'}</summary>
        <div className="px-2 pb-2 max-h-[50vh] overflow-y-auto no-scrollbar">
          {d.body.map(([h], i) => (
            <a key={h} href={`#s${i}`} className="flex items-center text-sm py-1.5 px-2 min-h-[24px] max-lg:min-h-[44px] rounded-lg text-[var(--muted)] hover:bg-[var(--surface-2)]">{h}</a>
          ))}
        </div>
      </details>

      <div className="grid md:grid-cols-[220px_1fr] gap-8 lg:gap-10">
        {/* Its own scroll region with a max height: a 32-entry contents list that is itself
            taller than the window cannot be used to navigate, which is the one job it has.
            `no-scrollbar` because the bar was the loudest thing in the column — a grey track
            running the full height beside a list of quiet grey links. The region still
            scrolls, by wheel, by drag, by keyboard and by focus; only the chrome is gone. */}
        <nav className="hidden md:block sticky top-20 self-start space-y-0.5 max-h-[calc(100vh-7rem)] overflow-y-auto no-scrollbar pe-1 print:hidden">
          <div className="text-[10px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1.5">{lang === 'fr' ? 'Sur cette page' : 'On this page'}</div>
          {d.body.map(([h], i) => (
            <a key={h} href={`#s${i}`}
              className={`flex items-center text-sm py-1 min-h-[24px] max-lg:min-h-[44px] border-s ps-2 -ms-px transition-colors ${
                active === i
                  ? 'text-[var(--accent-ink)] border-[var(--primary)] font-medium'
                  : 'text-[var(--muted)] border-transparent hover:text-[var(--accent-ink)] hover:border-[var(--primary)]'
              }`}>{h}</a>
          ))}
        </nav>
        <Card className="p-6 md:p-8 space-y-8">
          {d.body.map(([h, p], i) => (
            <section id={`s${i}`} key={h} className="scroll-mt-24 group">
              <h2 className="text-lg font-semibold mb-2.5 flex items-baseline gap-2.5">
                <span className="text-[var(--accent-ink)] font-mono text-xs tabular-nums shrink-0">{String(i + 1).padStart(2, '0')}</span>
                <span>{h}</span>
                {/* A permalink per section. People CITE these — "clause 14 of your terms" is
                    unusable, a link is not. Hidden until hover so it does not clutter, but
                    it is a real anchor, so keyboard focus reveals it too. */}
                <a href={`#s${i}`} aria-label={lang === 'fr' ? 'Lien vers cette section' : 'Link to this section'}
                  className="opacity-0 group-hover:opacity-100 focus:opacity-100 text-[var(--faint)] hover:text-[var(--accent-ink)] transition-opacity text-sm print:hidden">#</a>
              </h2>
              {/* Blank lines separate entries; inside one, a run of `· ` or `1. ` lines
                  becomes a real list. See LegalParagraph — no markdown parser is involved,
                  so nothing here can misread a policy and render it wrong. */}
              {d.markdown
                ? <div className="legal-md"><Markdown>{String(p)}</Markdown></div>
                : String(p).split('\n\n').map((para, k) => <LegalParagraph key={k} text={para} />)}
            </section>
          ))}
          <div className="pt-5 border-t border-[var(--line)] text-sm text-[var(--muted)] flex flex-wrap items-center justify-between gap-3">
            <span>{lang === 'fr' ? 'Des questions sur cette politique ? Contactez-nous via les liens du pied de page.' : 'Questions about this policy? Reach us via the links in the footer.'}</span>
            {/* Legal pages get saved and filed. print:hidden everywhere else keeps the
                printed copy to the document itself. */}
            <Button size="sm" variant="ghost" onClick={() => window.print()} className="print:hidden">
              <Printer size={13} /> {lang === 'fr' ? 'Imprimer' : 'Print'}
            </Button>
          </div>
        </Card>
      </div>
    </div>
  );
}


// A published version, exactly as it was when it was published.
//
// The admin screen linked here before this existed, so the link 404'd — the archive was a
// promise with nothing behind it. This is the page that makes `termsVersion` mean something:
// somebody who accepted v2 can read v2.
//
// It renders the SNAPSHOT and never the live sections, which is the entire point, and it says
// so on the page rather than leaving a reader to assume they are looking at the current text.
export function LegalArchive() {
  const { id } = useParams();
  const { lang, t } = useI18n();
  const [v, setV] = useState(undefined);   // undefined = loading, null = not found
  useEffect(() => {
    let alive = true;
    api.get(`/legal/versions/${id}`)
      .then((r) => { if (alive) setV(r); })
      .catch(() => { if (alive) setV(null); });
    return () => { alive = false; };
  }, [id]);

  if (v === undefined) return <div className="max-w-4xl mx-auto py-16"><Loading /></div>;
  if (v === null) {
    return (
      <div className="max-w-4xl mx-auto">
        <PageHeader icon={History} title={t('la.gone.t', 'Version not found')}
          subtitle={t('la.gone.s', 'This archived version does not exist, or its link is wrong.')} />
        <Link to="/legal"><Button size="sm"><ArrowLeft size={14} /> {t('la.back', 'All policies')}</Button></Link>
      </div>
    );
  }

  const sections = Array.isArray(v.sections) ? v.sections : [];
  const when = new Date(v.publishedAt).toLocaleDateString();
  const DOC_LABEL = {
    privacy: lang === 'fr' ? 'Confidentialité' : 'Privacy Policy',
    terms: lang === 'fr' ? 'Conditions' : 'Terms of Service',
    cookies: lang === 'fr' ? 'Cookies' : 'Cookie Policy',
    about: lang === 'fr' ? 'À propos' : 'About',
    refunds: lang === 'fr' ? 'Paiements & remboursements' : 'Payments & Refunds',
  };

  return (
    <div className="max-w-4xl mx-auto" id="legal-print">
      <PageHeader icon={History} title={`${DOC_LABEL[v.doc] || v.doc} — v${v.version}`}
        subtitle={`${lang === 'fr' ? 'Publié le' : 'Published'} ${when}`} />

      {/* An archived page that looks like the live one is a trap: somebody lands here from a
          search result and reads a superseded policy as current. The banner is not decoration. */}
      <Card className="p-4 mb-6 border-[var(--ring)]" style={{ background: 'color-mix(in srgb, var(--warning) 8%, transparent)' }}>
        <div className="flex items-start gap-3">
          <History size={18} className="text-[var(--warning)] shrink-0 mt-0.5" />
          <div className="text-sm">
            <div className="font-medium mb-1">{t('la.banner.t', 'This is an archived version')}</div>
            <p className="text-[var(--muted)] mb-2">
              {t('la.banner.d', 'Frozen when it was published and never edited since. It is kept so anyone who accepted this version can read exactly what they accepted. It may not be what applies today.')}
            </p>
            {v.note && <p className="text-[var(--muted)] mb-2"><span className="font-medium">{t('la.note', 'What changed')}:</span> {v.note}</p>}
            <Link to={`/legal/${v.doc}`} className="print:hidden">
              <Button size="sm"><ArrowRight size={14} /> {t('la.current', 'Read the current version')}</Button>
            </Link>
          </div>
        </div>
      </Card>

      <Card className="p-6 md:p-8 space-y-8">
        {sections.map((sec, i) => (
          <section key={i} className="scroll-mt-24">
            <h2 className="text-lg font-semibold mb-2.5 flex items-baseline gap-2.5">
              <span className="text-[var(--accent-ink)] font-mono text-xs tabular-nums shrink-0">{String(i + 1).padStart(2, '0')}</span>
              <span>{(lang === 'fr' && sec.titleFr) || sec.title}</span>
            </h2>
            <div className="legal-md"><Markdown>{String((lang === 'fr' && sec.bodyFr) || sec.body || '')}</Markdown></div>
          </section>
        ))}
        <div className="pt-5 border-t border-[var(--line)] text-sm text-[var(--muted)] flex flex-wrap items-center justify-between gap-3">
          <span>{t('la.foot', 'Archived version {v}, published {d}.').replace('{v}', `v${v.version}`).replace('{d}', when)}</span>
          <Button size="sm" variant="ghost" onClick={() => window.print()} className="print:hidden">
            <Printer size={13} /> {lang === 'fr' ? 'Imprimer' : 'Print'}
          </Button>
        </div>
      </Card>
    </div>
  );
}

// The /legal hub — lists every legal/policy document.
/**
 * The index, grouped.
 *
 * Five cards in one grid was the right shape for one product's policies. It stops being right
 * the moment a deployment carries several: "Terms of Service" and "Terms of Service" side by
 * side, one for each application, with nothing on either card saying which. The grouping is
 * the answer, and it is optional — a page with no category is listed on its own above the
 * headings, which is exactly what every page is today.
 */
export function LegalIndex() {
  const { lang, t } = useI18n();
  const L = LEGAL[lang] || LEGAL.en;
  const S = LEGAL_SUMMARY[lang] || LEGAL_SUMMARY.en;
  const [menu, setMenu] = useState(null);

  useEffect(() => {
    let alive = true;
    api.get('/legal')
      .then((r) => { if (alive) setMenu({ pages: r?.pages || [], categories: r?.categories || [] }); })
      // The compiled-in five, in their compiled-in order. A legal index that fails to load is
      // a site with no visible policies, which is worse than an index that is a version old.
      .catch(() => { if (alive) setMenu({ pages: BUILTIN_ORDER.filter((k) => !OPTIONAL_KEYS.includes(k)).map((k) => ({ key: k, builtIn: true })), categories: [] }); });
    return () => { alive = false; };
  }, []);

  if (!menu) return <div className="max-w-4xl mx-auto"><Loading /></div>;

  const pages = menu.pages.length ? menu.pages : BUILTIN_ORDER.filter((k) => !OPTIONAL_KEYS.includes(k)).map((k) => ({ key: k, builtIn: true }));
  const label = (x) => builtinLabel(x.key, t) || (lang === 'fr' && x.labelFr) || x.label || x.key;
  const blurb = (x) => S[x.key] || (lang === 'fr' && x.summaryFr) || x.summary || '';
  const title = (x) => L[x.key]?.title || label(x);

  const card = (x) => (
    <Link key={x.key} to={`/legal/${x.key}`} className="card card-hover p-5 flex items-start gap-3">
      <span className="grid place-items-center w-10 h-10 rounded-xl bg-[var(--surface-2)] text-[var(--accent-ink)] shrink-0">{docIcon(x.key, x.icon)}</span>
      <div className="min-w-0">
        <div className="font-semibold">{title(x)}</div>
        {blurb(x) && <div className="text-sm text-[var(--muted)] mt-0.5 line-clamp-2">{blurb(x)}</div>}
      </div>
    </Link>
  );

  const uncategorised = pages.filter((x) => !x.categoryId);
  const groups = menu.categories
    .map((c) => ({ c, items: pages.filter((x) => x.categoryId === c.id) }))
    .filter((g) => g.items.length);

  return (
    <div className="max-w-5xl mx-auto">
      <PageHeader icon={FileText} title={t('legal.title', 'Legal & policies')} subtitle={t('legal.sub', 'Our policies and terms, in plain language.')} />
      {!!uncategorised.length && (
        <div className="grid sm:grid-cols-2 gap-4">{uncategorised.map(card)}</div>
      )}
      {groups.map(({ c, items }) => (
        // The heading is an anchor target, so a project's own site can link straight to its
        // block: /legal#bmm rather than "scroll down to the third heading".
        <section key={c.id} id={c.key} className="mt-10 scroll-mt-24">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-[var(--faint)] mb-3">
            {(lang === 'fr' && c.labelFr) || c.label}
          </h2>
          <div className="grid sm:grid-cols-2 gap-4">{items.map(card)}</div>
        </section>
      ))}
    </div>
  );
}
